values ((select id from public.sections where slug = $c8294$cte$c8294$), (select id from public.lessons where slug = $c8295$cte-recursiva-jerarquias$c8295$), $c8296$cte-q08-partes-recursiva$c8296$, $c8297$matching$c8297$, $c8298$intermediate$c8298$, $c8299$Anatomía de una CTE recursiva$c8299$, $c8300$Relaciona cada parte de una CTE recursiva con su función.$c8300$, null, $c8301$Toda CTE recursiva combina estas piezas: de dónde parte, cómo avanza y qué la detiene. Sin la última, un ciclo en los datos deja la consulta corriendo hasta el tiempo límite.$c8301$, null, $c8302$[{"left":"SELECT ... FROM categories WHERE parent_id IS NULL","right":"Caso base: las filas con las que arranca el recorrido"},{"left":"UNION ALL","right":"Separa el caso base del paso recursivo y acumula las filas de cada vuelta"},{"left":"INNER JOIN arbol AS a ON a.id = c.parent_id","right":"Paso recursivo: busca los hijos de las filas ya encontradas"},{"left":"WHERE a.nivel < 10","right":"Cota de profundidad que protege de una recursión sin fin"}]$c8302$::jsonb, array[$c8303$cte$c8303$,$c8304$recursiva$c8304$]::text[], 75, true)
