insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c9006$acum-q09-dias-faltantes$c9006$), $c9009$b$c9009$, $c9010$Nada: `ROWS` siempre cuenta días cuando la clave de orden es una fecha.$c9010$, false, $c9011$`ROWS` cuenta filas presentes en el resultado, no unidades de tiempo. Los días ausentes simplemente no existen para la ventana.$c9011$, 1);

