insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c9432$lag-y-lead$c9432$), (select id from public.lessons where slug = $c9433$variaciones-entre-periodos$c9433$), $c9434$laglead-q06-lag-12-serie-incompleta$c9434$, $c9435$true_false$c9435$, $c9436$advanced$c9436$, $c9437$Comparación interanual$c9437$, $c9438$«`lag(ventas, 12) OVER (ORDER BY mes)` siempre devuelve el valor del mismo mes del año anterior.» ¿Verdadero o falso?$c9438$, null, $c9439$`lag(x, 12)` toma la fila que está doce posiciones atrás dentro de la partición. Coincide con «hace un año» solo si la serie tiene todos los meses. Si un mes no tuvo actividad y por eso no existe la fila, comparas contra el mes equivocado sin ningún aviso. Para comparar por calendario, une la serie consigo misma con `mes = otro.mes + interval '1 year'`.$c9439$, null, null, array[$c9440$lag_lead$c9440$,$c9441$offset$c9441$,$c9442$series$c9442$]::text[], 45, true)
