insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c9443$laglead-q06-lag-12-serie-incompleta$c9443$), $c9446$b$c9446$, $c9447$Verdadero: el desplazamiento se calcula sobre la fecha del `ORDER BY`.$c9447$, false, $c9448$El segundo argumento de `lag` cuenta filas, no unidades de tiempo. La ventana no sabe que tu clave de orden son meses.$c9448$, 1);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c9449$lag-y-lead$c9449$), (select id from public.lessons where slug = $c9450$brechas-y-valores-de-referencia$c9450$), $c9451$laglead-q07-interpretar-brechas$c9451$, $c9452$query_interpretation$c9452$, $c9453$intermediate$c9453$, $c9454$Brechas entre eventos$c9454$, $c9455$¿Qué mide la columna `d` de esta consulta?$c9455$, $c9456$SELECT
  user_id,
  played_at,
  extract(epoch FROM played_at
    - lag(played_at) OVER (PARTITION BY user_id ORDER BY played_at)) / 86400 AS d
FROM plays;$c9456$, $c9457$`played_at - lag(played_at)` da un `interval`; `extract(epoch FROM ...)` lo pasa a segundos y dividir entre 86 400 lo convierte en días. `PARTITION BY user_id` garantiza que la comparación sea contra la reproducción anterior de la misma persona. La primera reproducción de cada oyente devuelve `NULL`.$c9457$, null, null, array[$c9458$lag_lead$c9458$,$c9459$date_functions$c9459$]::text[], 70, true)
