values ((select id from public.theory_questions where slug = $c9485$laglead-q08-last-value-marco$c9485$), $c9486$a$c9486$, $c9487$Con `ORDER BY` y sin marco explícito, la ventana termina en la fila actual; hay que abrirla con `ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING`.$c9487$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c9485$laglead-q08-last-value-marco$c9485$), $c9488$b$c9488$, $c9489$`last_value` no admite `PARTITION BY` y por eso ignora el país.$c9489$, false, $c9490$Sí lo admite, y de hecho aquí funciona: el problema no es la partición sino hasta dónde llega el marco dentro de ella.$c9490$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c9485$laglead-q08-last-value-marco$c9485$), $c9491$c$c9491$, $c9492$Falta ordenar la consulta externa por `country, mes`.$c9492$, false, $c9493$El `ORDER BY` final solo cambia la presentación; los valores calculados por la ventana serían los mismos.$c9493$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c9485$laglead-q08-last-value-marco$c9485$), $c9494$d$c9494$, $c9495$`last_value` devuelve siempre la fila actual: es su comportamiento definido.$c9495$, false, $c9496$Devuelve la última fila **del marco**. Como el marco por omisión termina en la fila actual, parece hacer eso; con el marco abierto devuelve la última de la partición.$c9496$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c9497$lag-y-lead$c9497$), (select id from public.lessons where slug = $c9498$lag-y-lead-basico$c9498$), $c9499$laglead-q09-filtrar-por-lag$c9499$, $c9500$single$c9500$, $c9501$advanced$c9501$, $c9502$Orden de evaluación$c9502$, $c9503$Quieres quedarte solo con los meses que cayeron respecto del anterior. ¿Cuál es la forma correcta de filtrar?$c9503$, null, $c9504$El orden lógico es `FROM` → `WHERE` → `GROUP BY` → `HAVING` → funciones de ventana → `SELECT` → `ORDER BY`. Para filtrar por el resultado de una ventana necesitas un nivel más: CTE o subconsulta, y el `WHERE` afuera.$c9504$, null, null, array[$c9505$lag_lead$c9505$,$c9506$where$c9506$,$c9507$cte$c9507$]::text[], 55, true)
