values ((select id from public.theory_questions where slug = $c9508$laglead-q09-filtrar-por-lag$c9508$), $c9509$a$c9509$, $c9510$Calcular el `lag` en una CTE o subconsulta y aplicar el `WHERE` en la consulta externa.$c9510$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c9508$laglead-q09-filtrar-por-lag$c9508$), $c9511$b$c9511$, $c9512$Escribir `WHERE ventas < lag(ventas) OVER (ORDER BY mes)` en la misma consulta.$c9512$, false, $c9513$No es válido: el `WHERE` se evalúa antes que las funciones de ventana, así que Postgres rechaza la consulta con «window functions are not allowed in WHERE».$c9513$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c9508$laglead-q09-filtrar-por-lag$c9508$), $c9514$c$c9514$, $c9515$Usar `HAVING ventas < lag(ventas) OVER (ORDER BY mes)`.$c9515$, false, $c9516$`HAVING` también se evalúa antes que las ventanas, y además está pensado para condiciones sobre agregados de un `GROUP BY`.$c9516$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c9508$laglead-q09-filtrar-por-lag$c9508$), $c9517$d$c9517$, $c9518$Agregar `FILTER (WHERE ventas < 0)` a la llamada de `lag`.$c9518$, false, $c9519$`FILTER` solo se aplica a funciones de agregación, no a funciones de ventana puras como `lag`, y tampoco expresa esa condición.$c9519$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c9520$lag-y-lead$c9520$), (select id from public.lessons where slug = $c9521$brechas-y-valores-de-referencia$c9521$), $c9522$laglead-q10-emparejar-funciones$c9522$, $c9523$matching$c9523$, $c9524$intermediate$c9524$, $c9525$Funciones de posición$c9525$, $c9526$Relaciona cada función de ventana con lo que devuelve dentro de su partición (asumiendo el marco por omisión salvo que se indique otra cosa).$c9526$, null, $c9527$`lag` y `lead` son relativas a la fila actual; `first_value`, `last_value` y `nth_value` son absolutas dentro del marco. Por eso `last_value` depende tanto de la cláusula de marco: sin abrirla, «la última del marco» es la fila actual.$c9527$, null, $c9528$[{"left":"lag(x)","right":"El valor de x en la fila anterior"},{"left":"lead(x)","right":"El valor de x en la fila siguiente"},{"left":"first_value(x)","right":"El valor de x en la primera fila de la partición"},{"left":"last_value(x) con marco hasta UNBOUNDED FOLLOWING","right":"El valor de x en la última fila de la partición"},{"left":"nth_value(x, 3)","right":"El valor de x en la tercera fila del marco"}]$c9528$::jsonb, array[$c9529$lag_lead$c9529$,$c9530$first_value$c9530$,$c9531$last_value$c9531$]::text[], 80, true)
