values ((select id from public.theory_questions where slug = $c9821$cr-q12-indice-de-mes-restando-fechas$c9821$), $c9827$c$c9827$, $c9828$Un `interval` de 2 meses.$c9828$, false, $c9829$La resta de dos `date` devuelve un `integer` de días. El resultado sería un `interval` si los operandos fueran `timestamp`.$c9829$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c9821$cr-q12-indice-de-mes-restando-fechas$c9821$), $c9830$d$c9830$, $c9831$Un error: no se pueden restar dos columnas `date`.$c9831$, false, $c9832$La operación es válida y no falla; ese es justamente el riesgo, porque el resultado parece un índice de período razonable hasta que alguien lo mira de cerca.$c9832$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c9833$funnels$c9833$), (select id from public.lessons where slug = $c9834$funnel-definicion-y-pasos$c9834$), $c9835$fn-q01-tres-decisiones$c9835$, $c9836$single$c9836$, $c9837$easy$c9837$, $c9838$Definición de un funnel$c9838$, $c9839$Dos analistas miden el mismo funnel de compra sobre la misma base de datos y obtienen números distintos, sin errores de SQL en ninguna de las dos consultas. ¿Cuál es la causa más probable?$c9839$, null, $c9840$Un funnel no se define en SQL sino antes: unidad de conteo, pasos y su orden, y ventana de observación. Dos definiciones distintas producen dos funnels correctos y contradictorios; por eso las tres decisiones se publican junto con el resultado.$c9840$, null, null, array[$c9841$funnel$c9841$,$c9842$metodologia$c9842$]::text[], 45, true)
