insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c9883$fn-q03-filtro-en-on-o-where$c9883$), $c9884$a$c9884$, $c9885$El filtro `p.status = 'approved'` está en el `WHERE`; al descartar las filas con `p.status` NULL, el `LEFT JOIN` se comporta como un `INNER JOIN`. Debe ir en el `ON`.$c9885$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c9883$fn-q03-filtro-en-on-o-where$c9883$), $c9886$b$c9886$, $c9887$Falta un `GROUP BY o.id`.$c9887$, false, $c9888$La consulta devuelve una sola fila con dos totales; agrupar por `o.id` daría una fila por pedido, que no es lo que se pide.$c9888$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c9883$fn-q03-filtro-en-on-o-where$c9883$), $c9889$c$c9889$, $c9890$`count(DISTINCT o.id)` debería ser `count(*)`.$c9890$, false, $c9891$`count(*)` contaría filas del join, no pedidos, y con varios pagos por pedido daría un número aún mayor. El `DISTINCT` está bien puesto.$c9891$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c9883$fn-q03-filtro-en-on-o-where$c9883$), $c9892$d$c9892$, $c9893$El `LEFT JOIN` debería ser `RIGHT JOIN` para conservar todos los pedidos.$c9893$, false, $c9894$`orders` está a la izquierda, así que `LEFT JOIN` ya es el lado correcto. Un `RIGHT JOIN` conservaría todos los pagos y perdería los pedidos sin pago.$c9894$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c9895$funnels$c9895$), (select id from public.lessons where slug = $c9896$funnel-definicion-y-pasos$c9896$), $c9897$fn-q04-division-entera$c9897$, $c9898$query_interpretation$c9898$, $c9899$easy$c9899$, $c9900$Cálculo de tasas de conversión$c9900$, $c9901$`pedidos` y su valor del paso anterior son ambos de tipo `integer`. ¿Qué devuelve la columna `conversion` para el paso 2, donde hay 13 843 pedidos sobre 14 437 del paso 1?$c9901$, $c9902$```sql
SELECT paso,
       100 * pedidos / lag(pedidos) OVER (ORDER BY paso) AS conversion
FROM por_paso;
```$c9902$, $c9903$`100 * pedidos / lag(pedidos)` se evalúa de izquierda a derecha: primero `100 * 13843 = 1384300`, después `1384300 / 14437 = 95` con división entera. Escribir `100.0` fuerza `numeric` desde el principio y da 95.8925…, listo para `round(..., 2)`.$c9903$, null, null, array[$c9904$funnel$c9904$,$c9905$numeric_functions$c9905$]::text[], 50, true)
