insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c9931$funnels$c9931$), (select id from public.lessons where slug = $c9932$funnel-orden-estricto-o-cualquier-orden$c9932$), $c9933$fn-q06-estricto-vs-cualquier-orden$c9933$, $c9934$single$c9934$, $c9935$intermediate$c9935$, $c9936$Orden estricto contra cualquier orden$c9936$, $c9937$En Ritmo, 1225 usuarios tienen playlist y suscripción, pero solo 135 se suscribieron después de crear su primera playlist. ¿Qué afirmación es correcta?$c9937$, null, $c9938$Los 1090 usuarios de diferencia se suscribieron antes de armar su primera playlist. Si la pregunta de negocio es «¿armar una playlist empuja a suscribirse?», el único número relevante es el estricto; el otro confunde coincidencia con secuencia.$c9938$, null, null, array[$c9939$funnel$c9939$,$c9940$orden_temporal$c9940$]::text[], 60, true)
