values ((select id from public.theory_questions where slug = $c9941$fn-q06-estricto-vs-cualquier-orden$c9941$), $c9942$a$c9942$, $c9943$Ambos números son válidos y miden cosas distintas; hay que decir cuál se publica y por qué.$c9943$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c9941$fn-q06-estricto-vs-cualquier-orden$c9941$), $c9944$b$c9944$, $c9945$El 1225 está mal: un funnel siempre exige orden temporal.$c9945$, false, $c9946$«Alcanzó el paso» es una definición legítima y muy usada, por ejemplo para medir adopción de funcionalidades. Lo incorrecto es publicarla sin decir que no verifica el orden.$c9946$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c9941$fn-q06-estricto-vs-cualquier-orden$c9941$), $c9947$c$c9947$, $c9948$El 135 está mal: excluye usuarios que sí hicieron las dos cosas.$c9948$, false, $c9949$Los excluye a propósito, porque hicieron las dos cosas en el orden inverso. Esa exclusión es justamente lo que mide el funnel secuencial.$c9949$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c9941$fn-q06-estricto-vs-cualquier-orden$c9941$), $c9950$d$c9950$, $c9951$La diferencia se debe a usuarios con más de una playlist.$c9951$, false, $c9952$Ambas cifras parten del mismo `min(created_at)` por usuario, así que tener varias playlists no cambia nada: la diferencia es puramente de orden temporal.$c9952$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c9953$funnels$c9953$), (select id from public.lessons where slug = $c9954$funnel-orden-estricto-o-cualquier-orden$c9954$), $c9955$fn-q07-min-no-max$c9955$, $c9956$fill_blank$c9956$, $c9957$intermediate$c9957$, $c9958$El hito de cada paso$c9958$, $c9959$Para construir la tabla de hitos de un funnel secuencial, la marca de tiempo de cada paso se obtiene con la función de agregación `___(columna_de_fecha)` agrupando por unidad. Escribe el nombre de la función.$c9959$, null, $c9960$Se usa `min()`: el **primer** momento en que la unidad alcanzó ese paso. Con `max()` medirías la última vez que hizo la acción, y un usuario que armó una playlist en enero y otra en agosto podría pasar de cumplir el orden a no cumplirlo sin haber cambiado de comportamiento.$c9960$, $c9961${"accepted":["min","MIN","min()"],"case_sensitive":false}$c9961$::jsonb, null, array[$c9962$funnel$c9962$,$c9963$aggregate$c9963$]::text[], 40, true)
