values ((select id from public.theory_questions where slug = $c9976$fn-q08-condiciones-encadenadas$c9976$), $c9977$a$c9977$, $c9978$Debe repetir las condiciones de los pasos 2 y 3, no solo comparar el paso 4 con el 3.$c9978$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c9976$fn-q08-condiciones-encadenadas$c9976$), $c9979$b$c9979$, $c9980$Si un hito es `date` y el otro `timestamptz`, hay que fijar el huso explícitamente antes de compararlos.$c9980$, true, null, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c9976$fn-q08-condiciones-encadenadas$c9976$), $c9981$c$c9981$, $c9982$No hace falta comprobar que los hitos no sean NULL: una comparación con NULL nunca es verdadera, así que esas filas ya quedan fuera.$c9982$, true, null, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c9976$fn-q08-condiciones-encadenadas$c9976$), $c9983$d$c9983$, $c9984$Debe usar `OR` entre las condiciones de los pasos, para no perder usuarios que se saltaron alguno.$c9984$, false, $c9985$Con `OR` dejarías entrar caminos incompletos, que es exactamente lo que un funnel secuencial excluye. Las condiciones se combinan con `AND`.$c9985$, 3);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c9976$fn-q08-condiciones-encadenadas$c9976$), $c9986$e$c9986$, $c9987$Debe incluir siempre una ventana de conversión de 30 días.$c9987$, false, $c9988$La ventana es una decisión de negocio, no un requisito. Puede no haberla; lo obligatorio es declarar si existe o no.$c9988$, 4);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c9989$funnels$c9989$), (select id from public.lessons where slug = $c9990$funnel-orden-estricto-o-cualquier-orden$c9990$), $c9991$fn-q09-date-vs-timestamptz$c9991$, $c9992$true_false$c9992$, $c9993$advanced$c9993$, $c9994$Determinismo del huso horario$c9994$, $c9995$`started_on` es `date` y `created_at` es `timestamptz`. La condición `started_on >= created_at::date` produce el mismo resultado para cualquier persona que la ejecute.$c9995$, null, $c9996$Un `::date` o un `date_trunc` sobre `timestamptz` sin huso explícito es no determinista entre sesiones. La forma reproducible es `(created_at AT TIME ZONE 'UTC')::date`, que fija el calendario con el que se corta la fecha y deja el resultado igual para todo el mundo.$c9996$, null, null, array[$c9997$funnel$c9997$,$c9998$date_functions$c9998$]::text[], 45, true)
