insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c9999$fn-q09-date-vs-timestamptz$c9999$), $c10002$b$c10002$, $c10003$Verdadero$c10003$, false, $c10004$`created_at::date` convierte usando el parámetro `TimeZone` de la sesión. Un evento del 1 de marzo a las 02:00 UTC cae el 28 de febrero para una sesión en `America/Argentina/Buenos_Aires` y el 1 de marzo para una en UTC.$c10004$, 1);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c10005$funnels$c10005$), (select id from public.lessons where slug = $c10006$funnel-abandono-y-tiempo-de-conversion$c10006$), $c10007$fn-q10-ultimo-paso-alcanzado$c10007$, $c10008$query_interpretation$c10008$, $c10009$advanced$c10009$, $c10010$Punto de abandono$c10010$, $c10011$¿Qué propiedad tiene el resultado de esta consulta, que el funnel clásico (un conteo por evento) no tiene?$c10011$, $c10012$```sql
WITH avance AS (
  SELECT order_id,
         max(CASE event WHEN 'placed' THEN 1 WHEN 'accepted' THEN 2
                        WHEN 'preparing' THEN 3 WHEN 'picked_up' THEN 4
                        WHEN 'delivered' THEN 5 ELSE 0 END) AS ultimo_paso
  FROM order_events
  GROUP BY order_id
)
SELECT ultimo_paso, count(*) AS pedidos
FROM avance
GROUP BY ultimo_paso;
```$c10012$, $c10013$Clasificar por el último paso alcanzado convierte el funnel en una partición: cada unidad cae en una sola categoría y las cantidades suman el total. Es la tabla que responde «¿dónde priorizo?», mientras que el funnel acumulado responde «¿cuánto llega al final?».$c10013$, null, null, array[$c10014$funnel$c10014$,$c10015$case$c10015$,$c10016$aggregate$c10016$]::text[], 75, true)
