insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10017$fn-q10-ultimo-paso-alcanzado$c10017$), $c10018$a$c10018$, $c10019$Cada pedido aparece en una sola fila, así que las categorías son excluyentes y `pedidos` suma el total de pedidos.$c10019$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10017$fn-q10-ultimo-paso-alcanzado$c10017$), $c10020$b$c10020$, $c10021$Excluye los pedidos cancelados del resultado.$c10021$, false, $c10022$No los excluye: un pedido cancelado aparece con el número del último paso real que alcanzó, porque `cancelled` se mapea a 0 y `max()` se queda con el mayor.$c10022$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10017$fn-q10-ultimo-paso-alcanzado$c10017$), $c10023$c$c10023$, $c10024$Calcula la conversión paso a paso sin necesidad de `lag()`.$c10024$, false, $c10025$No calcula ninguna conversión. Da el reparto de abandonos; para las tasas de conversión hace falta el funnel acumulado.$c10025$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10017$fn-q10-ultimo-paso-alcanzado$c10017$), $c10026$d$c10026$, $c10027$Ordena los pedidos cronológicamente por su último evento.$c10027$, false, $c10028$No hay `ORDER BY` ni ninguna marca de tiempo en la consulta: `max()` opera sobre el número de paso, no sobre `event_at`.$c10028$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c10029$funnels$c10029$), (select id from public.lessons where slug = $c10030$funnel-abandono-y-tiempo-de-conversion$c10030$), $c10031$fn-q11-mediana-o-promedio$c10031$, $c10032$scenario$c10032$, $c10033$advanced$c10033$, $c10034$Resumir duraciones$c10034$, $c10035$Operaciones te pide «cuánto tarda un pedido típico en entregarse». La mayoría se entrega entre 30 y 45 minutos, pero un puñado de pedidos quedó trabado varias horas. ¿Qué métrica entregas?$c10035$, null, $c10036$Las duraciones casi siempre tienen cola larga, así que la mediana describe la experiencia típica mejor que el promedio. `percentile_cont` es una agregación de conjunto ordenado: el `ORDER BY` va dentro de `WITHIN GROUP`. El percentil 90 es el complemento habitual, porque es el lenguaje de los acuerdos de nivel de servicio.$c10036$, null, null, array[$c10037$funnel$c10037$,$c10038$aggregate$c10038$,$c10039$numeric_functions$c10039$]::text[], 70, true)
