insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10063$fn-q12-sesgo-de-supervivencia$c10063$), $c10066$b$c10066$, $c10067$Reemplazar los `delivered_at` nulos por la fecha de hoy para que todos los pedidos entren.$c10067$, false, $c10068$Inventa datos: un pedido cancelado hace un año pasaría a tener una duración de un año y la mediana dejaría de significar nada.$c10068$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10063$fn-q12-sesgo-de-supervivencia$c10063$), $c10069$c$c10069$, $c10070$Quitar el filtro y dejar que los NULL entren en el cálculo.$c10070$, false, $c10071$Las funciones de agregación ignoran los NULL, así que el resultado sería idéntico; lo único que cambiaría es que `count(*)` dejaría de referirse al mismo conjunto que la mediana.$c10071$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10063$fn-q12-sesgo-de-supervivencia$c10063$), $c10072$d$c10072$, $c10073$Nada: el filtro ya deja el cálculo correcto y el número se publica tal cual.$c10073$, false, $c10074$El cálculo es correcto, pero la lectura no. Sin la aclaración, quien lea el informe asumirá que el tiempo describe a todos los pedidos.$c10074$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c10075$deduplicacion$c10075$), (select id from public.lessons where slug = $c10076$dedup-que-es-un-duplicado$c10076$), $c10077$dedup-q01-quien-define-el-duplicado$c10077$, $c10078$single$c10078$, $c10079$easy$c10079$, $c10080$Qué convierte a dos filas en duplicados$c10080$, $c10081$Una tabla de eventos tiene dos filas con el mismo `user_id` y el mismo `product_id`. ¿Qué determina si son duplicados o dos eventos legítimos?$c10081$, null, $c10082$Deduplicar empieza fuera del SQL: alguien tiene que decidir qué columnas definen la identidad de una fila. En una tabla de reproducciones puede ser `(user_id, track_id, played_at)`; si solo tomaras `(user_id, track_id)`, borrarías escuchas repetidas legítimas. El motor ejecuta esa definición, no la inventa.$c10082$, null, null, array[$c10083$clave_de_identidad$c10083$,$c10084$criterio_de_negocio$c10084$]::text[], 45, true)
