values ((select id from public.theory_questions where slug = $c10138$dedup-q04-leer-consulta-de-deteccion$c10138$), $c10144$c$c10144$, $c10145$109 042$c10145$, false, $c10146$109 042 es la cantidad de combinaciones únicas de la clave, es decir el resultado **sin** el `HAVING`. El filtro deja fuera todos los grupos de una sola fila.$c10146$, 2);

