delete from public.question_options where question_id = (select id from public.theory_questions where slug = $c10247$dedup-q09-nulls-al-desempatar$c10247$);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10247$dedup-q09-nulls-al-desempatar$c10247$), $c10248$a$c10248$, $c10249$Con `DESC`, PostgreSQL coloca los NULL primero, así que los rechazos ganan el puesto 1. Se corrige con `ORDER BY paid_at DESC NULLS LAST`, agregando además un desempate único como `id DESC`.$c10249$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10247$dedup-q09-nulls-al-desempatar$c10247$), $c10250$b$c10250$, $c10251$Las filas con `paid_at` en NULL quedan fuera de la ventana y esos pedidos no aparecen en el resultado.$c10251$, false, $c10252$Las funciones de ventana no descartan filas por tener un NULL en la columna de orden: todas participan, solo cambia su posición dentro de la partición.$c10252$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10247$dedup-q09-nulls-al-desempatar$c10247$), $c10253$c$c10253$, $c10254$`row_number()` devuelve NULL para esas filas, por lo que el filtro `= 1` las excluye automáticamente.$c10254$, false, $c10255$`row_number()` siempre devuelve un entero correlativo desde 1; nunca devuelve NULL, sin importar el contenido de la columna de orden.$c10255$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10247$dedup-q09-nulls-al-desempatar$c10247$), $c10256$d$c10256$, $c10257$Con `DESC` los NULL van al final, así que el resultado ya es correcto y no hace falta cambiar nada.$c10257$, false, $c10258$Es al revés: en PostgreSQL el valor por omisión es `NULLS FIRST` con `DESC` y `NULLS LAST` con `ASC`. Conviene no confiar en la memoria y escribirlo explícito.$c10258$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c10259$deduplicacion$c10259$), (select id from public.lessons where slug = $c10260$dedup-clave-de-negocio$c10260$), $c10261$dedup-q10-distinct-tapa-cardinalidad$c10261$, $c10262$scenario$c10262$, $c10263$advanced$c10263$, $c10264$Filas repetidas por un join$c10264$, $c10265$Un reporte une `orders` con `payments` y la facturación sale más alta de lo esperado. Cada pedido puede tener varios intentos de pago. Un colega propone agregar `DISTINCT` al `SELECT`. ¿Qué conviene responder?$c10265$, null, $c10266$Vale la pena distinguir dos problemas que se parecen: **duplicados de datos** (la misma fila registrada dos veces) y **multiplicación por cardinalidad** (un join uno-a-muchos). El segundo no se arregla deduplicando el resultado, porque las filas no son iguales. Se arregla llevando el lado «muchos» a una fila por entidad antes de unir, con `GROUP BY`, `DISTINCT ON` o `ROW_NUMBER`. Si tu reflejo ante un total inflado es agregar `DISTINCT`, casi siempre estás tapando un error de cardinalidad.$c10266$, null, null, array[$c10267$cardinalidad$c10267$,$c10268$join$c10268$,$c10269$distinct$c10269$]::text[], 85, true)
