insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10294$dedup-q11-count-tras-left-join$c10294$), $c10295$a$c10295$, $c10296$`count(*)` cuenta filas, y el `LEFT JOIN` produce una fila con las columnas de `orders` en NULL para los clientes sin pedidos. Hay que usar `count(o.id)`, que ignora los NULL.$c10296$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10294$dedup-q11-count-tras-left-join$c10294$), $c10297$b$c10297$, $c10298$El `LEFT JOIN` debería ser `INNER JOIN`: así los clientes sin pedidos no generan filas fantasma.$c10298$, false, $c10299$Con `INNER JOIN` esos clientes desaparecen por completo del resultado en lugar de aparecer con 0. Para una regla de desempate necesitas que sigan compitiendo, aunque sea con cero pedidos.$c10299$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10294$dedup-q11-count-tras-left-join$c10294$), $c10300$c$c10300$, $c10301$Falta `o.id` en el `GROUP BY`, y por eso el conteo queda mal calculado.$c10301$, false, $c10302$Agregar `o.id` al `GROUP BY` produciría una fila por pedido en lugar de una por cliente. El nivel de agregación actual es el correcto; lo que está mal es qué se cuenta.$c10302$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10294$dedup-q11-count-tras-left-join$c10294$), $c10303$d$c10303$, $c10304$Hay que envolver el resultado en `coalesce(count(*), 0)`.$c10304$, false, $c10305$`count` nunca devuelve NULL: devuelve 0 cuando no hay nada que contar. `coalesce` no cambia nada aquí, porque el valor devuelto es 1, no NULL.$c10305$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c10306$deduplicacion$c10306$), (select id from public.lessons where slug = $c10307$dedup-elegir-la-fila-ganadora$c10307$), $c10308$dedup-q12-orden-de-la-limpieza$c10308$, $c10309$single$c10309$, $c10310$advanced$c10310$, $c10311$Secuencia segura de una limpieza$c10311$, $c10312$Ya identificaste las cuentas duplicadas y elegiste la ganadora de cada grupo. ¿Cuál es la secuencia correcta para ejecutar la limpieza?$c10312$, null, $c10313$Deduplicar no termina con un `DELETE`. La secuencia sana es: detectar → cuantificar → elegir ganadora con una regla escrita → entregar la lista para revisión → repuntar las dependencias → eliminar → recién entonces prevenir con un índice único funcional. Cada paso deja evidencia, y esa evidencia es lo que te permite responder tres meses después por qué una métrica cambió.$c10313$, null, null, array[$c10314$proceso$c10314$,$c10315$integridad_referencial$c10315$,$c10316$auditoria$c10316$]::text[], 60, true)
