values ((select id from public.theory_questions where slug = $c10442$calidad-q06-not-in-con-nulos$c10442$), $c10443$a$c10443$, $c10444$`NOT IN` compara contra cada valor de la lista; al haber un NULL, ninguna comparación puede dar falso con certeza, el resultado global queda en desconocido y ninguna fila pasa el filtro.$c10444$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10442$calidad-q06-not-in-con-nulos$c10442$), $c10445$b$c10445$, $c10446$`NOT IN` no acepta subconsultas, solo listas escritas a mano.$c10446$, false, $c10447$`NOT IN` acepta subconsultas sin problema; la consulta es sintácticamente válida y por eso no aparece ningún error.$c10447$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10442$calidad-q06-not-in-con-nulos$c10442$), $c10448$c$c10448$, $c10449$La subconsulta devuelve demasiadas filas y el motor la trunca silenciosamente.$c10449$, false, $c10450$PostgreSQL no trunca resultados de subconsultas. El problema no es el tamaño sino la presencia de un solo NULL.$c10450$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10442$calidad-q06-not-in-con-nulos$c10442$), $c10451$d$c10451$, $c10452$Falta un `DISTINCT` en la subconsulta y los valores repetidos se anulan entre sí.$c10452$, false, $c10453$Los valores repetidos no afectan el resultado de `NOT IN`; agregar `DISTINCT` no cambiaría nada mientras el NULL siga ahí.$c10453$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c10454$calidad-de-datos$c10454$), (select id from public.lessons where slug = $c10455$calidad-de-datos-perfilar-una-tabla$c10455$), $c10456$calidad-q07-having-para-duplicados$c10456$, $c10457$single$c10457$, $c10458$advanced$c10458$, $c10459$Detectar claves duplicadas$c10459$, $c10460$Quieres comprobar si la combinación (`user_id`, `track_id`, `played_at`) identifica una sola fila en `plays`. ¿Cuál de estas consultas responde esa pregunta?$c10460$, null, $c10461$Probar una clave de negocio es agrupar por ella y quedarse con los grupos de más de una fila. La clave técnica (`id`) no sirve para esto porque es distinta por definición en cada fila; el duplicado siempre se define respecto de las columnas que el negocio considera identificatorias.$c10461$, null, null, array[$c10462$duplicados$c10462$,$c10463$group_by$c10463$,$c10464$having$c10464$]::text[], 70, true)
