insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10488$calidad-q08-tablero-de-chequeos$c10488$), $c10489$a$c10489$, $c10490$Las ramas se apilan con `UNION ALL` y no con `UNION`, porque dos chequeos distintos pueden fallar la misma cantidad de filas y `UNION` eliminaría uno de ellos.$c10490$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10488$calidad-q08-tablero-de-chequeos$c10488$), $c10491$b$c10491$, $c10492$Los chequeos que devuelven cero también se muestran: una regla ausente del reporte no se distingue de una regla que nadie verificó.$c10492$, true, null, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10488$calidad-q08-tablero-de-chequeos$c10488$), $c10493$c$c10493$, $c10494$Junto al conteo que falla conviene mostrar el total de filas evaluadas, porque 340 filas significan cosas distintas en una tabla de mil y en una de un millón.$c10494$, true, null, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10488$calidad-q08-tablero-de-chequeos$c10488$), $c10495$d$c10495$, $c10496$Como todas las ramas cuentan filas, la columna de conteos siempre se puede sumar para obtener «el total de filas con problemas».$c10496$, false, $c10497$No siempre cuentan lo mismo: un chequeo de duplicados suele contar **claves** y no filas, y una misma fila puede romper dos reglas. Sumar la columna mezcla unidades y cuenta filas dos veces.$c10497$, 3);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10488$calidad-q08-tablero-de-chequeos$c10488$), $c10498$e$c10498$, $c10499$El reporte debería borrar las filas que incumplen para que la próxima ejecución salga limpia.$c10499$, false, $c10500$Auditar no es corregir. Borrar datos de una tabla ajena destruye la evidencia y suele romper conciliaciones contables; el rol del análisis es documentar, cuantificar y proponer el arreglo en el sistema de origen.$c10500$, 4);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c10501$calidad-de-datos$c10501$), (select id from public.lessons where slug = $c10502$calidad-de-datos-validez-y-huecos$c10502$), $c10503$calidad-q09-tipos-de-chequeo$c10503$, $c10504$matching$c10504$, $c10505$advanced$c10505$, $c10506$Familias de chequeos de calidad$c10506$, $c10507$Relaciona cada problema de calidad con la familia de chequeo que lo detecta.$c10507$, null, $c10508$Nombrar la familia de cada hallazgo no es burocracia: define a quién se le reclama y cómo se arregla. La completitud y el dominio se resuelven en la captura del dato; las reglas cruzadas y los huecos referenciales, casi siempre en la lógica de la aplicación que escribe las filas.$c10508$, null, $c10509$[{"left":"`seconds_played` con valor −240","right":"Regla de dominio: un solo campo fuera de su rango posible"},{"left":"`seconds_played` mayor que `tracks.duration_seconds`","right":"Regla cruzada: la fila contradice a la tabla que la define"},{"left":"Un pedido sin ninguna fila en `order_items`","right":"Hueco referencial: el padre existe pero no tiene hijos"},{"left":"Dos filas con el mismo oyente, canción e instante","right":"Unicidad: la clave de negocio no identifica una sola fila"},{"left":"1745 reproducciones sin `device`","right":"Completitud: falta el valor de una columna"}]$c10509$::jsonb, array[$c10510$auditoria$c10510$,$c10511$dominio$c10511$,$c10512$integridad-referencial$c10512$]::text[], 90, true)
