insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10549$calidad-q11-normalizar-antes-de-agrupar$c10549$), $c10550$a$c10550$, $c10551$Hay 37 correos que, una vez ignorados los espacios y las mayúsculas, están cargados en más de una fila: son personas registradas dos veces que el conteo de `email` distintos no detectaba.$c10551$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10549$calidad-q11-normalizar-antes-de-agrupar$c10549$), $c10552$b$c10552$, $c10553$Hay 37 filas con el correo vacío o nulo.$c10553$, false, $c10554$La consulta no busca ausencias; agrupa por el correo normalizado y se queda con los grupos de más de una fila. Las filas con correo nulo formarían un solo grupo aparte.$c10554$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10549$calidad-q11-normalizar-antes-de-agrupar$c10549$), $c10555$c$c10555$, $c10556$Hay 37 filas duplicadas exactas, idénticas en todas sus columnas.$c10556$, false, $c10557$El criterio de la consulta es solo el correo normalizado; el resto de las columnas puede diferir. Además, 37 es la cantidad de **grupos**, no de filas sobrantes.$c10557$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10549$calidad-q11-normalizar-antes-de-agrupar$c10549$), $c10558$d$c10558$, $c10559$El resultado es incorrecto: `GROUP BY` no admite expresiones, solo columnas.$c10559$, false, $c10560$`GROUP BY` acepta expresiones sin problema, y de hecho es la única manera de agrupar por un valor normalizado sin crear antes una columna nueva.$c10560$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c10561$calidad-de-datos$c10561$), (select id from public.lessons where slug = $c10562$calidad-de-datos-perfilar-una-tabla$c10562$), $c10563$calidad-q12-primer-dia-con-la-tabla$c10563$, $c10564$scenario$c10564$, $c10565$advanced$c10565$, $c10566$Prioridades al recibir una tabla desconocida$c10566$, $c10567$Entras a un equipo de datos y te piden «el reporte de escucha semanal» sobre una tabla que nadie documentó. Tienes acceso de solo lectura y medio día. ¿Cuál es la mejor primera acción?$c10567$, null, $c10568$Perfilar primero cuesta minutos y cambia el reporte entero: descubrir que la clave de negocio se repite, que falta el 1,6 % de un campo o que la carga se cortó hace tres semanas es la diferencia entre un número defendible y uno que habrá que retirar. El perfil se guarda como consulta para volver a correrlo cada vez que el dato cambie.$c10568$, null, null, array[$c10569$profiling$c10569$,$c10570$metodo$c10570$,$c10571$comunicacion$c10571$]::text[], 90, true)
