insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10594$dc-q01-consulta-que-corre-no-es-correcta$c10594$), $c10597$b$c10597$, $c10598$Que el resultado es correcto, porque el motor valida la lógica de la consulta.$c10598$, false, $c10599$El motor no conoce la pregunta del negocio. Verifica sintaxis y tipos; una suma multiplicada por un join 1:N es tan válida para Postgres como la suma correcta.$c10599$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10594$dc-q01-consulta-que-corre-no-es-correcta$c10594$), $c10600$c$c10600$, $c10601$Que no hay joins que multipliquen filas, porque eso produciría un error.$c10601$, false, $c10602$El fan-out no produce ningún error: es una operación perfectamente legal que simplemente devuelve más filas de las que esperabas.$c10602$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10594$dc-q01-consulta-que-corre-no-es-correcta$c10594$), $c10603$d$c10603$, $c10604$Que los datos de origen no tienen NULL en las columnas usadas.$c10604$, false, $c10605$Los NULL tampoco generan errores. Cambian silenciosamente el resultado de comparaciones, promedios y conteos.$c10605$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c10606$depuracion-de-consultas$c10606$), (select id from public.lessons where slug = $c10607$depuracion-descomponer-y-contar$c10607$), $c10608$dc-q02-count-star-vs-count-distinct$c10608$, $c10609$single$c10609$, $c10610$intermediate$c10610$, $c10611$Diagnóstico del grano$c10611$, $c10612$En una consulta sobre `orders` con varios joins, `count(*)` devuelve 21 974 y `count(DISTINCT o.id)` devuelve 13 156. ¿Qué te dice esa diferencia?$c10612$, null, $c10613$La pareja `count(*)` / `count(DISTINCT clave)` es el diagnóstico más rápido del grano. Mientras coincidan, hay una fila por entidad; cuando se separan, un join 1:N repitió filas y toda agregación sobre columnas de la tabla repetida queda multiplicada.$c10613$, null, null, array[$c10614$depuracion$c10614$,$c10615$grano$c10615$,$c10616$join$c10616$]::text[], 60, true)
