insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10617$dc-q02-count-star-vs-count-distinct$c10617$), $c10618$a$c10618$, $c10619$Que algún join multiplicó filas: cada pedido aparece más de una vez, así que sumar o promediar columnas de `orders` dará un resultado inflado.$c10619$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10617$dc-q02-count-star-vs-count-distinct$c10617$), $c10620$b$c10620$, $c10621$Que 8 818 pedidos están duplicados en la tabla `orders`.$c10621$, false, $c10622$`orders.id` es clave primaria: no hay duplicados en la tabla. Las filas repetidas las produce el join, no el origen.$c10622$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10617$dc-q02-count-star-vs-count-distinct$c10617$), $c10623$c$c10623$, $c10624$Que hay 8 818 filas con `o.id` en NULL.$c10624$, false, $c10625$`count(DISTINCT o.id)` ignora los nulos, pero aquí el `INNER JOIN` viene de una clave primaria y no genera nulos. La brecha se explica por repetición, no por ausencia.$c10625$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10617$dc-q02-count-star-vs-count-distinct$c10617$), $c10626$d$c10626$, $c10627$Que falta un `GROUP BY` en la consulta.$c10627$, false, $c10628$Los dos conteos son agregados de toda la consulta y no necesitan `GROUP BY`. Agregarlo no cambiaría el hecho de que el join repite pedidos.$c10628$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c10629$depuracion-de-consultas$c10629$), (select id from public.lessons where slug = $c10630$depuracion-joins-que-multiplican$c10630$), $c10631$dc-q03-error-fan-out-suma$c10631$, $c10632$error_diagnosis$c10632$, $c10633$intermediate$c10633$, $c10634$Fan-out en sumas$c10634$, $c10635$Esta consulta debería devolver los ingresos por país de los pedidos entregados. Devuelve aproximadamente el doble de lo que informa Finanzas. ¿Cuál es la causa?$c10635$, $c10636$```sql
SELECT c.country, round(sum(o.total_amount), 2) AS ingresos
FROM orders AS o
INNER JOIN customers AS c ON c.id = o.customer_id
INNER JOIN order_items AS oi ON oi.order_id = o.id
WHERE o.status = 'delivered'
GROUP BY 1;
```$c10636$, $c10637$`order_items` tiene 30 067 líneas para 18 000 pedidos: la relación es 1:N. Como `total_amount` vive en `orders`, el join lo repite. La corrección es quitar ese join (no aporta nada a la pregunta) o agregar `order_items` en una CTE con una fila por `order_id` antes de unir.$c10637$, null, null, array[$c10638$depuracion$c10638$,$c10639$join$c10639$,$c10640$fan-out$c10640$]::text[], 80, true)
