values ((select id from public.theory_questions where slug = $c10641$dc-q03-error-fan-out-suma$c10641$), $c10642$a$c10642$, $c10643$El join con `order_items` repite cada pedido una vez por línea, así que `total_amount` se suma tantas veces como líneas tenga el pedido.$c10643$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10641$dc-q03-error-fan-out-suma$c10641$), $c10644$b$c10644$, $c10645$Falta un `HAVING sum(o.total_amount) > 0` para excluir pedidos sin importe.$c10645$, false, $c10646$Los pedidos con importe cero no cambian una suma. El problema es de repetición de filas, no de filas con valor cero.$c10646$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10641$dc-q03-error-fan-out-suma$c10641$), $c10647$c$c10647$, $c10648$`GROUP BY 1` agrupa por la posición equivocada y mezcla países.$c10648$, false, $c10649$`GROUP BY 1` agrupa por la primera columna del `SELECT`, que es `c.country`. Es equivalente a `GROUP BY c.country`.$c10649$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10641$dc-q03-error-fan-out-suma$c10641$), $c10650$d$c10650$, $c10651$El `INNER JOIN` con `customers` descarta pedidos y por eso el total se desvía.$c10651$, false, $c10652$Ese join descartaría filas, lo que bajaría el total, no lo duplicaría. Además `customer_id` apunta siempre a un cliente existente.$c10652$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c10653$depuracion-de-consultas$c10653$), (select id from public.lessons where slug = $c10654$depuracion-joins-que-multiplican$c10654$), $c10655$dc-q04-sum-distinct-no-corrige$c10655$, $c10656$true_false$c10656$, $c10657$intermediate$c10657$, $c10658$DISTINCT como corrección$c10658$, $c10659$`sum(DISTINCT o.total_amount)` es una forma válida de corregir un total inflado por un join que multiplica filas.$c10659$, null, $c10660$`DISTINCT` sirve para contar entidades (`count(DISTINCT o.id)`), porque la clave identifica la entidad. Para sumar importes no sirve: la corrección real es volver al grano de una fila por pedido, agregando el detalle antes de unir.$c10660$, null, null, array[$c10661$depuracion$c10661$,$c10662$join$c10662$,$c10663$distinct$c10663$]::text[], 45, true)
