insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10706$dc-q06-not-in-con-nulos$c10706$), $c10709$b$c10709$, $c10710$Las 24 categorías que no son padre de ninguna otra.$c10710$, false, $c10711$Ese es el resultado que se buscaba, pero no el que se obtiene: con un NULL en la lista, `NOT IN` no puede devolver verdadero para ningún valor.$c10711$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10706$dc-q06-not-in-con-nulos$c10706$), $c10712$c$c10712$, $c10713$Las 6 categorías raíz, porque su `parent_id` es NULL.$c10713$, false, $c10714$La condición compara `c.id` contra los valores de `parent_id`, no contra el `parent_id` de cada fila. Y aunque así fuera, el NULL en la lista anula el resultado.$c10714$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10706$dc-q06-not-in-con-nulos$c10706$), $c10715$d$c10715$, $c10716$Un error: `NOT IN` no acepta subconsultas que devuelvan NULL.$c10716$, false, $c10717$Es sintaxis válida y se ejecuta sin advertencias. Precisamente por eso el error pasa desapercibido.$c10717$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c10718$depuracion-de-consultas$c10718$), (select id from public.lessons where slug = $c10719$depuracion-filtros-nulos-y-grano$c10719$), $c10720$dc-q07-not-exists-inmune$c10720$, $c10721$fill_blank$c10721$, $c10722$intermediate$c10722$, $c10723$Reescritura inmune a NULL$c10723$, $c10724$Completa la palabra clave que reemplaza a `NOT IN` sin sufrir el problema de los NULL, porque pregunta por la existencia de una fila en lugar de comparar valores: `WHERE NOT ______ (SELECT 1 FROM categories AS h WHERE h.parent_id = c.id)`.$c10724$, null, $c10725$`NOT EXISTS` evalúa si la subconsulta produce alguna fila. No compara valores, así que los NULL no intervienen: devuelve verdadero o falso, nunca NULL. Es la reescritura preferida de `NOT IN` y suele ser también la más eficiente, porque se detiene en la primera coincidencia.$c10725$, $c10726${"accepted":["EXISTS","exists"],"case_sensitive":false}$c10726$::jsonb, null, array[$c10727$depuracion$c10727$,$c10728$null$c10728$,$c10729$exists$c10729$]::text[], 50, true)
