insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10742$dc-q08-avg-ignora-nulos$c10742$), $c10743$a$c10743$, $c10744$`avg` excluye los 222 nulos del numerador y del divisor; `sum(horas) / count(*)` los excluye del numerador pero los cuenta en el divisor, y el promedio queda más bajo.$c10744$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10742$dc-q08-avg-ignora-nulos$c10742$), $c10745$b$c10745$, $c10746$No hay diferencia: `avg` es exactamente `sum` dividido por `count(*)`.$c10746$, false, $c10747$`avg` equivale a `sum(x) / count(x)`, no a `sum(x) / count(*)`. La diferencia aparece justamente cuando hay nulos.$c10747$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10742$dc-q08-avg-ignora-nulos$c10742$), $c10748$c$c10748$, $c10749$`avg` trata los nulos como cero y por eso da un valor más bajo.$c10749$, false, $c10750$Es al revés: `avg` los ignora. Quien los trata implícitamente como cero es la división por `count(*)`.$c10750$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10742$dc-q08-avg-ignora-nulos$c10742$), $c10751$d$c10751$, $c10752$`sum` devuelve NULL en cuanto hay un NULL entre los valores, así que falla.$c10752$, false, $c10753$`sum` ignora los nulos y devuelve NULL solo cuando **todos** los valores lo son o el conjunto está vacío.$c10753$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c10754$depuracion-de-consultas$c10754$), (select id from public.lessons where slug = $c10755$depuracion-joins-que-multiplican$c10755$), $c10756$dc-q09-grano-del-promedio$c10756$, $c10757$scenario$c10757$, $c10758$advanced$c10758$, $c10759$Grano de la agregación$c10759$, $c10760$Te piden el ticket promedio por canal. Tu consulta une `orders` con `order_items` y calcula `avg(o.total_amount)`. El resultado da un 28 % por encima del que informa facturación. ¿Cuál es la lectura correcta de tu número?$c10760$, null, $c10761$Dividir el número inflado por el promedio de líneas tampoco lo arregla, porque la ponderación no es uniforme. Hay que volver al grano de la entidad medida: una CTE con una fila por pedido y después `avg(total_amount)`. Verificación rápida: `promedio * pedidos` debe reconstruir el ingreso conocido del grupo.$c10761$, null, null, array[$c10762$depuracion$c10762$,$c10763$grano$c10763$,$c10764$promedio$c10764$]::text[], 90, true)
