insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10765$dc-q09-grano-del-promedio$c10765$), $c10768$b$c10768$, $c10769$Es el ticket promedio correcto, y facturación está excluyendo pedidos que tú incluyes.$c10769$, false, $c10770$La diferencia no viene de la población sino del grano: la misma población promediada al grano de línea pesa más a los pedidos de varias líneas.$c10770$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10765$dc-q09-grano-del-promedio$c10765$), $c10771$c$c10771$, $c10772$Es el valor promedio de una línea de pedido, que es una métrica distinta pero igual de útil.$c10772$, false, $c10773$El valor promedio de una línea saldría de promediar `quantity * unit_price`. Aquí se promedia el total del pedido repetido por cada línea, que no mide ni el pedido ni la línea.$c10773$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10765$dc-q09-grano-del-promedio$c10765$), $c10774$d$c10774$, $c10775$Es el ticket promedio con impuestos, mientras que facturación lo informa sin ellos.$c10775$, false, $c10776$El join con `order_items` no agrega impuestos a nada; solo repite filas. La diferencia es estructural, no de definición fiscal.$c10776$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c10777$depuracion-de-consultas$c10777$), (select id from public.lessons where slug = $c10778$depuracion-joins-que-multiplican$c10778$), $c10779$dc-q10-inner-join-que-elimina$c10779$, $c10780$single$c10780$, $c10781$intermediate$c10781$, $c10782$Joins que eliminan filas$c10782$, $c10783$Un informe sobre «todos los pedidos» agrega un `INNER JOIN shipments` para mostrar el transportista. ¿Qué efecto tiene sobre la población del informe?$c10783$, null, $c10784$Cada vez que agregues un join conviene responder dos preguntas con una consulta, no con una intuición: ¿puede multiplicar filas? ¿puede eliminarlas? Si puede eliminar y no quieres perder población, es un `LEFT JOIN`.$c10784$, null, null, array[$c10785$depuracion$c10785$,$c10786$join$c10786$,$c10787$cobertura$c10787$]::text[], 60, true)
