insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10788$dc-q10-inner-join-que-elimina$c10788$), $c10791$b$c10791$, $c10792$Ninguno: un join nunca quita filas, solo agrega columnas.$c10792$, false, $c10793$Un `INNER JOIN` conserva únicamente las filas con coincidencia en ambos lados; las que no la tienen desaparecen.$c10793$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10788$dc-q10-inner-join-que-elimina$c10788$), $c10794$c$c10794$, $c10795$Multiplica los pedidos, porque `shipments` es una tabla de detalle.$c10795$, false, $c10796$Podría multiplicar si un pedido tuviera varios envíos, pero el efecto que se pregunta aquí, y el más probable con «todos los pedidos», es la pérdida de los que no tienen ninguno.$c10796$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10788$dc-q10-inner-join-que-elimina$c10788$), $c10797$d$c10797$, $c10798$Convierte los pedidos sin envío en filas con NULL en las columnas de `shipments`.$c10798$, false, $c10799$Eso haría un `LEFT JOIN`. El `INNER JOIN` no rellena con NULL: elimina la fila.$c10799$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c10800$depuracion-de-consultas$c10800$), (select id from public.lessons where slug = $c10801$depuracion-descomponer-y-contar$c10801$), $c10802$dc-q11-mensajes-de-error$c10802$, $c10803$matching$c10803$, $c10804$intermediate$c10804$, $c10805$Lectura de mensajes de error$c10805$, $c10806$Relaciona cada mensaje de Postgres con el diagnóstico que conviene revisar primero.$c10806$, null, $c10807$Un error visible es información gratis. El reflejo útil no es silenciarlo (agregar la columna al `GROUP BY`, envolver todo en `min()`, poner un `LIMIT 1`) sino leer qué supuesto sobre los datos acaba de romperse. El peligro real está en la consulta que no protesta.$c10807$, null, $c10808$[{"left":"column \"o.total_amount\" must appear in the GROUP BY clause or be used in an aggregate function","right":"Seleccionas una columna a un grano distinto del grupo: define cuál es el grano de la consulta"},{"left":"more than one row returned by a subquery used as an expression","right":"La subconsulta escalar devuelve varias filas: hay un problema de grano o falta un filtro"},{"left":"operator does not exist: text = integer","right":"Comparas columnas de tipos distintos: revisa qué guarda realmente cada columna"},{"left":"division by zero","right":"El denominador quedó vacío: protégelo con nullif y averigua por qué no tenía filas"}]$c10808$::jsonb, array[$c10809$depuracion$c10809$,$c10810$errores$c10810$,$c10811$postgres$c10811$]::text[], 100, true)
