insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c10875$casos-de-negocio$c10875$), (select id from public.lessons where slug = $c10876$de-un-pedido-vago-a-una-especificacion$c10876$), $c10877$cn-q03-descomponer-ingresos$c10877$, $c10878$scenario$c10878$, $c10879$intermediate$c10879$, $c10880$Descomposición de métricas$c10880$, $c10881$Los ingresos de agosto cayeron 9 % contra julio. Calculaste que los pedidos bajaron 8 % y que el ticket promedio quedó prácticamente igual. ¿Cuál es la conclusión que se desprende de esos números?$c10881$, null, $c10882$Descomponer ingresos en pedidos × ticket permite ver cuál de los dos factores se movió. Aquí el ticket queda quieto y los pedidos caen: el problema es de volumen, y esa es una conversación distinta a la de precios.$c10882$, null, null, array[$c10883$casos-de-negocio$c10883$,$c10884$metricas$c10884$,$c10885$diagnostico$c10885$]::text[], 70, true)
