insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10947$cn-q06-inner-join-supuesto$c10947$), $c10950$b$c10950$, $c10951$Que todos los movimientos están en la misma moneda.$c10951$, false, $c10952$Ese también es un problema real de la consulta, pero no lo introduce el join: lo introduce el `sum()` sobre importes de monedas distintas. La pregunta es por el supuesto que agrega esta línea de más.$c10952$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10947$cn-q06-inner-join-supuesto$c10947$), $c10953$c$c10953$, $c10954$Que el mes se calcula en la zona horaria de la sesión.$c10954$, false, $c10955$Justamente no: `AT TIME ZONE 'UTC'` fija el huso, que es lo correcto. Esa parte de la consulta está bien.$c10955$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10947$cn-q06-inner-join-supuesto$c10947$), $c10956$d$c10956$, $c10957$Que los movimientos `pending` se cuentan como completados.$c10957$, false, $c10958$El `WHERE t.status = 'completed'` los excluye explícitamente. Es un supuesto declarado en el código, no uno escondido.$c10958$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c10959$casos-de-negocio$c10959$), (select id from public.lessons where slug = $c10960$supuestos-que-se-escriben$c10960$), $c10961$cn-q07-tipo-de-cambio-del-dia$c10961$, $c10962$single$c10962$, $c10963$advanced$c10963$, $c10964$Conversión de monedas$c10964$, $c10965$Preparas un informe mensual histórico que convierte importes locales a dólares. ¿Por qué conviene usar la cotización del día de cada operación en lugar de la cotización de hoy?$c10965$, null, $c10966$Convertir con la cotización de hoy reescribe el pasado en cada ejecución: la serie cambia sin que haya cambiado ningún dato. La cotización del día de la operación congela la historia y hace auditable el informe.$c10966$, null, null, array[$c10967$casos-de-negocio$c10967$,$c10968$supuestos$c10968$,$c10969$fx$c10969$]::text[], 70, true)
