insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10994$cn-q08-ended-on-null$c10994$), $c10997$b$c10997$, $c10998$`count(*)` no cuenta las filas con algún valor nulo.$c10998$, false, $c10999$`count(*)` cuenta filas, tengan o no nulos. La pérdida ocurre antes, en el `WHERE`, que descarta las filas cuya condición no es verdadera.$c10999$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10994$cn-q08-ended-on-null$c10994$), $c11000$c$c11000$, $c11001$Falta `AT TIME ZONE 'UTC'` en las comparaciones de fecha.$c11001$, false, $c11002$`started_on` y `ended_on` son de tipo `date`, no `timestamptz`: no tienen hora ni huso, así que la zona horaria no interviene.$c11002$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c10994$cn-q08-ended-on-null$c10994$), $c11003$d$c11003$, $c11004$El operador correcto sería `>=` en lugar de `>`.$c11004$, false, $c11005$Cambiar el operador mueve el resultado en una sola fila por período que termina exactamente ese día; no explica una diferencia grande, y sigue perdiendo todas las filas con `ended_on` nulo.$c11005$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c11006$casos-de-negocio$c11006$), (select id from public.lessons where slug = $c11007$supuestos-que-se-escriben$c11007$), $c11008$cn-q09-donde-se-esconden$c11008$, $c11009$matching$c11009$, $c11010$intermediate$c11010$, $c11011$Dónde se esconden los supuestos$c11011$, $c11012$Relaciona cada decisión silenciosa de una consulta con el supuesto de negocio que introduce.$c11012$, null, $c11013$Cada línea de una consulta de negocio codifica una definición. Filtros, joins, tratamiento de nulos, unidades y ventanas de tiempo son los cinco lugares donde más seguido se esconde un supuesto que nadie escribió.$c11013$, null, $c11014$[{"left":"`INNER JOIN` con la tabla de comercios","right":"Solo cuentan los pagos en comercios"},{"left":"`status = 'completed'`","right":"Los pagos pendientes no forman parte de la métrica"},{"left":"`sum(amount)` sobre varias monedas","right":"Los importes de distintas monedas son sumables"},{"left":"`coalesce(rating, 0)` en un promedio","right":"No tener calificación equivale a tener cero"},{"left":"`created_at >= now() - INTERVAL '30 days'`","right":"El resultado cambia cada día que se ejecuta"}]$c11014$::jsonb, array[$c11015$casos-de-negocio$c11015$,$c11016$supuestos$c11016$]::text[], 90, true)
