insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11053$cn-q11-umbral-minimo$c11053$), $c11056$b$c11056$, $c11057$Sacar `samba` de la tabla porque el número no parece razonable.$c11057$, false, $c11058$Eliminar una fila puntual porque no gusta el resultado es elegir la conclusión. La regla tiene que ser una sola, definida de antemano y aplicada a todos por igual.$c11058$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11053$cn-q11-umbral-minimo$c11053$), $c11059$c$c11059$, $c11060$Dejarlo tal cual: el dato es correcto y quien lee sabrá interpretarlo.$c11060$, false, $c11061$El dato es correcto y la lectura es engañosa igual: la primera fila de una tabla ordenada se lee como la conclusión. Con cuatro casos, el porcentaje no es interpretable.$c11061$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11053$cn-q11-umbral-minimo$c11053$), $c11062$d$c11062$, $c11063$Reemplazar el porcentaje por la diferencia absoluta de oyentes en toda la tabla.$c11063$, false, $c11064$La diferencia absoluta es información útil y conviene mostrarla, pero por sí sola favorece siempre a los géneros grandes. No sustituye al umbral: lo complementa.$c11064$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c11065$casos-de-negocio$c11065$), (select id from public.lessons where slug = $c11066$revisar-antes-de-enviar$c11066$), $c11067$cn-q12-correlacion-no-es-causa$c11067$, $c11068$scenario$c11068$, $c11069$advanced$c11069$, $c11070$Qué se puede concluir de una comparación$c11070$, $c11071$Mediste que quienes estrenaron la app con el cupón de bienvenida recompran 45,20 % (177 clientes) contra 40,12 % de quienes estrenaron sin promoción (2777 clientes). Marketing quiere titular «el cupón aumenta la fidelidad 5 puntos». ¿Qué corresponde responder?$c11071$, null, $c11072$Cuando los grupos se autoseleccionan, la diferencia observada mezcla el efecto de la intervención con el de quién la eligió. Lo que se entrega es la asociación, el tamaño de la muestra y la propuesta de medirlo bien: asignación aleatoria en la próxima campaña.$c11072$, null, null, array[$c11073$casos-de-negocio$c11073$,$c11074$interpretacion$c11074$,$c11075$revision$c11075$]::text[], 90, true)
