values ((select id from public.theory_questions where slug = $c11399$avanzado-q-cube-vs-rollup$c11399$), $c11402$b$c11402$, $c11403$Falso$c11403$, false, $c11404$`CUBE (a, b)` calcula las cuatro combinaciones posibles: `(a, b)`, `(a)`, `(b)` y `()`. El que deja afuera el subtotal de la segunda dimensión sola es `ROLLUP`.$c11404$, 1);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c11405$sql-analitico-avanzado$c11405$), (select id from public.lessons where slug = $c11406$avanzado-consultas-en-capas$c11406$), $c11407$avanzado-q-lateral-palabra-clave$c11407$, $c11408$fill_blank$c11408$, $c11409$advanced$c11409$, $c11410$LATERAL$c11410$, $c11411$Completa la palabra clave que permite que la subconsulta del `FROM` use `a.id`, una columna de la tabla que está a su izquierda.$c11411$, $c11412$SELECT a.name, t.title
FROM artists AS a
CROSS JOIN ______ (
  SELECT al.title
  FROM albums AS al
  WHERE al.artist_id = a.id
  ORDER BY al.released_on DESC
  LIMIT 1
) AS t;$c11412$, $c11413$`LATERAL` habilita que una subconsulta del `FROM` referencie columnas de los elementos que la preceden. Sin ella, PostgreSQL responde `invalid reference to FROM-clause entry for table "a"`.$c11413$, $c11414${"accepted":["LATERAL","lateral"],"case_sensitive":false}$c11414$::jsonb, null, array[$c11415$lateral$c11415$,$c11416$subconsulta$c11416$,$c11417$from$c11417$]::text[], 60, true)
