insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c11443$sql-analitico-avanzado$c11443$), (select id from public.lessons where slug = $c11444$avanzado-consultas-en-capas$c11444$), $c11445$avanzado-q-ventana-en-mismo-where$c11445$, $c11446$error_diagnosis$c11446$, $c11447$advanced$c11447$, $c11448$Orden de evaluación$c11448$, $c11449$Esta consulta falla. ¿Cuál es la causa y la corrección adecuada?$c11449$, $c11450$SELECT category, name, operaciones,
       row_number() OVER (PARTITION BY category ORDER BY operaciones DESC) AS puesto
FROM pagos
WHERE puesto <= 3
ORDER BY category, puesto;$c11450$, $c11451$El orden de evaluación es `FROM` → `WHERE` → `GROUP BY` → `HAVING` → funciones de ventana → `SELECT` → `ORDER BY` → `LIMIT`. Filtrar por el resultado de una ventana siempre exige una capa adicional.$c11451$, null, null, array[$c11452$window function$c11452$,$c11453$where$c11453$,$c11454$cte$c11454$]::text[], 90, true)
