insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11479$avanzado-q-agregado-anidado$c11479$), $c11482$b$c11482$, $c11483$Reemplazar `sum(count(*))` por `count(*)`.$c11483$, false, $c11484$Eso divide cada grupo por sí mismo: todos los porcentajes darían 100.$c11484$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11479$avanzado-q-agregado-anidado$c11479$), $c11485$c$c11485$, $c11486$Agregar `m.category` al `GROUP BY` una segunda vez.$c11486$, false, $c11487$Repetir una columna en el `GROUP BY` no cambia nada; el problema es la anidación de agregados, no la agrupación.$c11487$, 2);

