values ((select id from public.theory_questions where slug = $c11525$avanzado-q-json-vs-jsonb$c11525$), $c11534$d$c11534$, $c11535$Con `jsonb` la consulta falla si las claves no están en orden alfabético.$c11535$, false, $c11536$Puedes escribir las claves en cualquier orden; `jsonb` las reordena al almacenarlas, sin error.$c11536$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c11537$sql-analitico-avanzado$c11537$), (select id from public.lessons where slug = $c11538$avanzado-arrays-y-json$c11538$), $c11539$avanzado-q-funciones-de-lista$c11539$, $c11540$matching$c11540$, $c11541$advanced$c11541$, $c11542$Arrays y JSON$c11542$, $c11543$Relaciona cada función o operador con lo que devuelve.$c11543$, null, $c11544$Son las cinco piezas que aparecen una y otra vez al trabajar con listas, documentos y subtotales. Ojo con `->` frente a `->>`: el primero devuelve JSON (el texto queda entre comillas) y el segundo, texto plano.$c11544$, null, $c11545$[{"left":"array_to_string(lista, ' > ')","right":"Un texto con los elementos unidos por el separador"},{"left":"cardinality(lista)","right":"La cantidad de elementos del array"},{"left":"unnest(lista)","right":"Una fila por cada elemento del array"},{"left":"documento ->> 'clave'","right":"El valor de esa clave como texto plano"},{"left":"grouping(columna)","right":"1 si la fila es un subtotal que agregó esa columna, 0 si no"}]$c11545$::jsonb, array[$c11546$array$c11546$,$c11547$json$c11547$,$c11548$funciones$c11548$]::text[], 120, true)
