insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11609$pf-q01-pregunta-lista-para-escribir$c11609$), $c11610$a$c11610$, $c11611$Acordar qué devuelve cada fila del resultado y con qué definición (por ejemplo: una fila por mes de alta, con el porcentaje de personas que volvieron a comprar entre el día 30 y el 60).$c11611$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11609$pf-q01-pregunta-lista-para-escribir$c11609$), $c11612$b$c11612$, $c11613$Escribir una consulta exploratoria sobre la tabla más grande para ver qué columnas hay disponibles y decidir a partir de eso.$c11613$, false, $c11614$Explorar el esquema es útil, pero no reemplaza la definición. Si dejas que las columnas disponibles definan la métrica, terminas respondiendo la pregunta que los datos permiten y no la que el negocio hizo.$c11614$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11609$pf-q01-pregunta-lista-para-escribir$c11609$), $c11615$c$c11615$, $c11616$Calcular la retención con la definición estándar de la industria y entregarla; si no les sirve, la ajustas después.$c11616$, false, $c11617$No existe una definición estándar única de retención: cambia el evento que cuenta, la ventana y el denominador. Entregar un número sin acordar la definición es la forma más rápida de que alguien decida con la métrica equivocada.$c11617$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11609$pf-q01-pregunta-lista-para-escribir$c11609$), $c11618$d$c11618$, $c11619$Pedir acceso a más tablas, porque una sola tabla nunca alcanza para calcular retención.$c11619$, false, $c11620$La cantidad de tablas es una consecuencia de la definición, no un paso previo. Con una tabla de eventos y una fecha de alta ya se puede calcular retención.$c11620$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c11621$proyectos-finales$c11621$), (select id from public.lessons where slug = $c11622$proyectos-finales-planificar-antes-de-escribir$c11622$), $c11623$pf-q02-rango-semiabierto$c11623$, $c11624$single$c11624$, $c11625$intermediate$c11625$, $c11626$Rangos de fechas sobre marcas de tiempo$c11626$, $c11627$`orders.placed_at` es `timestamptz`. Quieres los pedidos del primer semestre de 2025 en UTC, sin perder ninguno. ¿Cuál condición es correcta?$c11627$, null, $c11628$La forma segura de acotar un período sobre marcas de tiempo es el rango semiabierto: `>=` el inicio y `<` el inicio del período siguiente. No depende de la precisión de la columna (segundos, milisegundos) y nunca deja horas fuera. Sobre `timestamptz` hay que fijar además el huso, o el resultado cambia según quién ejecute la consulta.$c11628$, null, null, array[$c11629$fechas$c11629$,$c11630$rangos$c11630$,$c11631$timestamptz$c11631$]::text[], 60, true)
