delete from public.question_options where question_id = (select id from public.theory_questions where slug = $c11710$pf-q06-diagnostico-inner-join-ratings$c11710$);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11710$pf-q06-diagnostico-inner-join-ratings$c11710$), $c11711$a$c11711$, $c11712$El join a `ratings` es interno: descarta los pedidos entregados que nadie calificó, así que `delivered_orders` cuenta pedidos calificados y no pedidos entregados. Debe ser `LEFT JOIN`.$c11712$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11710$pf-q06-diagnostico-inner-join-ratings$c11710$), $c11713$b$c11713$, $c11714$Falta `HAVING count(*) > 0`, porque los restaurantes sin calificaciones producen grupos vacíos que el motor descarta mal.$c11714$, false, $c11715$Un grupo vacío no existe: si no hay filas, no hay grupo. `HAVING count(*) > 0` no cambia nada, y el problema es de qué filas llegan a la agregación, no de cómo se filtran los grupos.$c11715$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11710$pf-q06-diagnostico-inner-join-ratings$c11710$), $c11716$c$c11716$, $c11717$`avg` no puede usarse junto a `count(*)` en el mismo `SELECT` cuando una de las tablas tiene valores nulos.$c11717$, false, $c11718$Sí puede: `avg` ignora los `NULL` y `count(*)` cuenta todas las filas del grupo. Convivir en el mismo `SELECT` es justamente lo que permite reportar ambos números.$c11718$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11710$pf-q06-diagnostico-inner-join-ratings$c11710$), $c11719$d$c11719$, $c11720$El `WHERE o.status = 'delivered'` debería estar en el `ON` del join a `ratings` para no perder filas.$c11720$, false, $c11721$Mover ese filtro al `ON` de `ratings` no recupera ningún pedido: el filtro es sobre `orders` y con un join interno los pedidos sin calificación se pierden igual.$c11721$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c11722$proyectos-finales$c11722$), (select id from public.lessons where slug = $c11723$proyectos-finales-del-curso-al-trabajo$c11723$), $c11724$pf-q07-pedido-de-negocio-y-tecnica$c11724$, $c11725$matching$c11725$, $c11726$intermediate$c11726$, $c11727$Del pedido de negocio a la técnica adecuada$c11727$, $c11728$Relaciona cada pedido tal como llega en el trabajo con la técnica que lo resuelve.$c11728$, null, $c11729$Casi todos los pedidos de una vacante de analista caen en unas pocas familias. Reconocer a cuál pertenece un pedido en los primeros treinta segundos es lo que separa una tarde de trabajo de una semana: la técnica ya la sabes, lo que hay que entrenar es el mapeo.$c11729$, null, $c11730$[{"left":"«¿La gente que se registró en marzo sigue usando el producto?»","right":"Cohortes por mes de alta con ventanas relativas a la fecha de registro"},{"left":"«¿En qué paso del registro se nos cae la gente?»","right":"Funnel con pasos ordenados en el tiempo y denominador fijo"},{"left":"«Dame los 5 vendedores más grandes de cada país»","right":"ROW_NUMBER con PARTITION BY país y un criterio de desempate explícito"},{"left":"«Este total no coincide con el informe de finanzas»","right":"Reconciliación: recalcular la métrica sin joins y comparar dos caminos"},{"left":"«La misma persona aparece dos veces en el listado»","right":"Deduplicación por clave de negocio con una regla de fila ganadora"}]$c11730$::jsonb, array[$c11731$cohortes$c11731$,$c11732$funnels$c11732$,$c11733$ranking$c11733$,$c11734$calidad$c11734$]::text[], 90, true)
