insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11747$pf-q08-chequeos-antes-de-entregar$c11747$), $c11748$a$c11748$, $c11749$Comparar la cantidad de filas obtenida con la que predijiste a partir de la granularidad declarada.$c11749$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11747$pf-q08-chequeos-antes-de-entregar$c11747$), $c11750$b$c11750$, $c11751$Recalcular el total de la métrica principal directamente sobre la tabla base, sin joins, y compararlo con la suma del informe.$c11751$, true, null, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11747$pf-q08-chequeos-antes-de-entregar$c11747$), $c11752$c$c11752$, $c11753$Verificar que agregar el último `LEFT JOIN` no aumentó la cantidad de filas de la tabla principal.$c11753$, true, null, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11747$pf-q08-chequeos-antes-de-entregar$c11747$), $c11754$d$c11754$, $c11755$Confirmar que la consulta corre sin errores y devuelve resultados en menos de un segundo.$c11755$, false, $c11756$Que corra rápido y sin errores no dice nada sobre si el número es correcto. Los errores que importan en un informe son silenciosos: filas multiplicadas, filtros que borran grupos, definiciones equivocadas.$c11756$, 3);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11747$pf-q08-chequeos-antes-de-entregar$c11747$), $c11757$e$c11757$, $c11758$Ajustar la definición de la métrica hasta que el total coincida con el informe que circula hoy en la empresa.$c11758$, false, $c11759$Eso es acomodar la métrica al resultado esperado. Si tu número difiere del que circula, el trabajo es explicar la diferencia, no hacerla desaparecer: muchas veces el informe viejo es el que está mal.$c11759$, 4);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c11760$proyectos-finales$c11760$), (select id from public.lessons where slug = $c11761$proyectos-finales-planificar-antes-de-escribir$c11761$), $c11762$pf-q09-conversion-con-tipo-de-cambio$c11762$, $c11763$single$c11763$, $c11764$advanced$c11764$, $c11765$Convertir importes con una tabla de tipos de cambio$c11765$, $c11766$`fx_rates(rate_date, currency, usd_rate)` guarda cuántas unidades de moneda local equivalen a un dólar (por ejemplo, `ARS` con `usd_rate = 1200`). Necesitas el importe en dólares de cada transacción, incluidas las que ya están en `USD`, que no tienen fila en esa tabla. ¿Qué expresión es correcta?$c11766$, null, $c11767$Una conversión multimoneda tiene tres decisiones: la dirección (dividir o multiplicar, según cómo esté expresada la cotización), la fecha (la del evento, no la de hoy) y el caso sin cotización (la propia moneda de referencia). `LEFT JOIN` más `coalesce(usd_rate, 1)` resuelve el tercero sin escribir un caso especial.$c11767$, null, null, array[$c11768$multimoneda$c11768$,$c11769$fx$c11769$,$c11770$left_join$c11770$]::text[], 75, true)
