insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11918$optimizacion-q04-not-in-con-nulos$c11918$), $c11919$a$c11919$, $c11920$0 filas$c11920$, true, null, 0);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11918$optimizacion-q04-not-in-con-nulos$c11918$), $c11921$b$c11921$, $c11922$73 filas: los repartidores activos sin entregas en agosto$c11922$, false, $c11923$Ese es el resultado que la persona que escribió la consulta esperaba, y el que devuelve la versión con `NOT EXISTS`. Con `NOT IN` y un `NULL` en la subconsulta, la condición nunca llega a ser verdadera.$c11923$, 1);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11918$optimizacion-q04-not-in-con-nulos$c11918$), $c11924$c$c11924$, $c11925$503 filas: todos los repartidores activos$c11925$, false, $c11926$Eso ocurriría si la condición fuera siempre verdadera. Con un `NULL` en la lista pasa exactamente lo contrario: nunca es verdadera.$c11926$, 2);

insert into public.question_options (question_id, key, body_md, is_correct, why_incorrect_md, sort_order)
values ((select id from public.theory_questions where slug = $c11918$optimizacion-q04-not-in-con-nulos$c11918$), $c11927$d$c11927$, $c11928$La consulta falla con un error de comparación contra NULL$c11928$, false, $c11929$No hay error. Ese es el peligro real: la consulta se ejecuta sin problemas y devuelve un resultado vacío que se confunde con «no hay casos».$c11929$, 3);

insert into public.theory_questions (section_id, lesson_id, slug, type, difficulty, topic, prompt_md, code_md, explanation_md, answer, pairs, tags, estimated_seconds, is_published)
values ((select id from public.sections where slug = $c11930$fundamentos-de-optimizacion$c11930$), (select id from public.lessons where slug = $c11931$optimizacion-reducir-antes-de-unir$c11931$), $c11932$optimizacion-q05-anti-join-mal-escrito$c11932$, $c11933$error_diagnosis$c11933$, $c11934$advanced$c11934$, $c11935$Condiciones del lado débil en el WHERE$c11935$, $c11936$El objetivo es listar los restaurantes activos **sin** ningún pedido entregado en agosto de 2025. La consulta se ejecuta sin errores y devuelve cero filas. ¿Cuál es el problema?$c11936$, $c11937$SELECT r.id, r.name
FROM restaurants AS r
LEFT JOIN orders AS o ON o.restaurant_id = r.id
WHERE r.is_active
  AND o.status = 'delivered'
  AND o.placed_at >= TIMESTAMPTZ '2025-08-01 00:00:00+00'
  AND o.id IS NULL;$c11937$, $c11938$En un `LEFT JOIN`, las filas sin coincidencia llegan al `WHERE` con todas las columnas de `orders` en `NULL`. Cualquier condición como `o.status = 'delivered'` en el `WHERE` las descarta, convirtiendo el `LEFT JOIN` en un `INNER JOIN`; y entonces `o.id IS NULL` no puede cumplirse nunca. El patrón correcto de *anti join* pone todas las condiciones del lado débil en el `ON` y deja en el `WHERE` solo `o.id IS NULL`. La alternativa más clara es `NOT EXISTS`.$c11938$, null, null, array[$c11939$left_join$c11939$,$c11940$anti_join$c11940$,$c11941$on_vs_where$c11941$]::text[], 80, true)
