FROM restaurants AS r
LEFT JOIN orders AS o
  ON o.restaurant_id = r.id
 AND o.placed_at >= '2025-08-01'
 AND o.placed_at < '2025-09-01'
WHERE r.city_id = 8
GROUP BY r.id, r.name
ORDER BY pedidos_agosto DESC, r.id;$c13580$, true, 'reference', 0);

