delete from public.exercise_solutions where exercise_id = (select id from public.exercises where slug = $c13680$saldo-acumulado-de-la-cuenta-2364$c13680$);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c13681$saldo-acumulado-de-la-cuenta-2364$c13681$), $c13682$SELECT
  id,
  created_at,
  direction,
  amount,
  sum(CASE WHEN direction = 'credit' THEN amount ELSE -amount END)
    OVER (ORDER BY created_at, id) AS saldo
