insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c13934$referencia-de-transferencia$c13934$), $c13935$SELECT id,
       account_id,
       SPLIT_PART(description, '#', 2) AS referencia,
       REPLACE(REPLACE(kind, 'transfer_out', 'Enviada'), 'transfer_in', 'Recibida') AS tipo
FROM transactions
WHERE kind IN ('transfer_in', 'transfer_out')
  AND amount > 900000;$c13935$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c13936$referencia-de-transferencia$c13936$), $c13937$SELECT id,
       account_id,
       SUBSTRING(description FROM POSITION('#' IN description) + 1) AS referencia,
       REPLACE(REPLACE(kind, 'transfer_out', 'Enviada'), 'transfer_in', 'Recibida') AS tipo
