WHERE description LIKE 'Transferencia #%'
  AND amount > 900000;$c13937$, false, $c13938$Con SUBSTRING y POSITION, filtrando por el patrón del texto$c13938$, 1);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c13939$referencia-de-transferencia$c13939$), $c13940$SELECT id,
