insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c14262$cumplimiento-de-entregas-de-septiembre$c14262$), $c14263$SELECT
  id,
  carrier,
  destination_city,
  CASE
    WHEN delivered_at IS NULL THEN 'En tránsito'
    WHEN delivered_at <= shipped_at + INTERVAL '5 days' THEN 'A tiempo'
    ELSE 'Tarde'
  END AS cumplimiento
FROM shipments
WHERE shipped_at >= DATE '2025-09-01';$c14263$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c14264$cumplimiento-de-entregas-de-septiembre$c14264$), $c14265$SELECT
  id,
  carrier,
  destination_city,
  CASE
    WHEN delivered_at IS NULL THEN 'En tránsito'
    WHEN delivered_at - shipped_at <= INTERVAL '5 days' THEN 'A tiempo'
    ELSE 'Tarde'
  END AS cumplimiento
FROM shipments
WHERE shipped_at >= DATE '2025-09-01';$c14265$, false, $c14266$Diferencia entre timestamps$c14266$, 1);

