ORDER BY id;$c14301$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c14302$riesgo-de-movimientos-marcados$c14302$), $c14303$SELECT
