insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c14412$dias-de-entrega-por-envio$c14412$), $c14413$SELECT order_id, shipped_at, delivered_at, CAST(delivered_at AS date) - CAST(shipped_at AS date) AS delivery_days FROM shipments WHERE shipped_at >= DATE '2025-09-01' AND shipped_at < DATE '2025-09-08' AND delivered_at IS NOT NULL ORDER BY delivery_days DESC, order_id;$c14413$, false, $c14414$Con CAST explícito$c14414$, 1);

