insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c14676$comision-de-retiro-con-minimo-y-tope$c14676$), $c14677$SELECT id,
       amount,
       LEAST(GREATEST(ROUND(amount * 0.015, 2), 5.00), 12.00) AS fee,
       ROUND(amount - LEAST(GREATEST(ROUND(amount * 0.015, 2), 5.00), 12.00), 2) AS net_amount
FROM transactions
WHERE kind = 'withdrawal'
  AND status = 'completed'
  AND currency = 'PEN';$c14677$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c14678$comision-de-retiro-con-minimo-y-tope$c14678$), $c14679$SELECT id,
       amount,
       GREATEST(5.00, LEAST(12.00, ROUND(amount * 1.5 / 100, 2))) AS fee,
       ROUND(amount - GREATEST(5.00, LEAST(12.00, ROUND(amount * 1.5 / 100, 2))), 2) AS net_amount
FROM transactions
WHERE kind = 'withdrawal'
  AND status = 'completed'
  AND currency = 'PEN';$c14679$, false, $c14680$Tope primero y tasa como 1.5/100$c14680$, 1);

