insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c14789$clientes-mayoristas-mexico$c14789$), $c14790$WITH por_cliente AS (SELECT customer_id, count(*) AS pedidos, sum(total_amount) AS gasto FROM orders WHERE currency = 'MXN' AND status = 'delivered' GROUP BY customer_id) SELECT customer_id, pedidos, gasto FROM por_cliente WHERE pedidos >= 8 AND gasto > 200000 ORDER BY gasto DESC, customer_id;$c14790$, false, $c14791$CTE y filtro con WHERE sobre los agregados$c14791$, 1);

