insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c14971$reversos-con-su-pago-original$c14971$), $c14972$SELECT
  rev.id AS reversal_id,
  orig.id AS original_id,
  orig.amount,
  (extract(epoch FROM (rev.created_at - orig.created_at)) / 3600)::int AS horas_hasta_reverso
