insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c15008$posibles-publicaciones-duplicadas$c15008$), $c15009$SELECT
  a.seller_id,
  a.id AS producto_a,
  b.id AS producto_b,
  a.list_price AS precio_a,
  b.list_price AS precio_b
FROM products AS a
INNER JOIN products AS b
  ON b.seller_id = a.seller_id
 AND b.category_id = a.category_id
 AND b.id > a.id
WHERE abs(a.list_price - b.list_price) <= 0.05 * least(a.list_price, b.list_price)
ORDER BY a.seller_id, producto_a, producto_b;$c15009$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c15010$posibles-publicaciones-duplicadas$c15010$), $c15011$SELECT
