insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c15126$productos-mas-vendidos-con-tienda-y-categoria$c15126$), $c15127$SELECT
  p.name AS product_name,
  s.store_name,
  cat.name AS category_name,
  sum(oi.quantity) AS unidades
FROM orders AS o
INNER JOIN order_items AS oi ON oi.order_id = o.id
INNER JOIN products AS p ON p.id = oi.product_id
INNER JOIN sellers AS s ON s.id = p.seller_id
INNER JOIN categories AS cat ON cat.id = p.category_id
WHERE o.created_at >= '2025-01-01'
  AND o.status <> 'cancelled'
GROUP BY p.name, s.store_name, cat.name
HAVING sum(oi.quantity) >= 24
ORDER BY unidades DESC, product_name;$c15127$, true, 'reference', 0);

