insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c15282$pedidos-sobre-el-ticket-promedio-uruguay$c15282$), $c15283$SELECT
  o.id,
  o.created_at,
  o.total_amount,
  (SELECT round(avg(o2.total_amount), 2)
   FROM orders AS o2
   WHERE o2.currency = 'UYU' AND o2.status = 'delivered') AS ticket_promedio
FROM orders AS o
WHERE o.currency = 'UYU'
  AND o.status = 'delivered'
  AND o.total_amount > (SELECT avg(o3.total_amount)
                        FROM orders AS o3
                        WHERE o3.currency = 'UYU' AND o3.status = 'delivered');$c15283$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c15284$pedidos-sobre-el-ticket-promedio-uruguay$c15284$), $c15285$SELECT
  o.id,
  o.created_at,
  o.total_amount,
  round(m.prom, 2) AS ticket_promedio
FROM orders AS o
CROSS JOIN (
  SELECT avg(total_amount) AS prom
  FROM orders
  WHERE currency = 'UYU' AND status = 'delivered'
) AS m
WHERE o.currency = 'UYU'
  AND o.status = 'delivered'
  AND o.total_amount > m.prom;$c15285$, false, $c15286$Tabla derivada con el promedio y CROSS JOIN$c15286$, 1);

