insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c15472$gasto-promedio-por-pais$c15472$), $c15473$WITH gasto_por_cliente AS (
  SELECT c.id AS customer_id, c.country, sum(o.total_amount) AS gasto
  FROM orders AS o
  INNER JOIN customers AS c ON c.id = o.customer_id
  WHERE o.status = 'delivered'
    AND o.created_at >= DATE '2025-01-01'
  GROUP BY c.id, c.country
)
SELECT
  country,
  count(*) AS clientes,
  round(avg(gasto), 2) AS gasto_promedio
FROM gasto_por_cliente
GROUP BY country
ORDER BY country;$c15473$, true, 'reference', 0);

