insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c15589$arbol-de-categorias$c15589$), $c15590$WITH RECURSIVE arbol(id, name, parent_id, nivel, ruta) AS (
  SELECT id, name, parent_id, 1, name
  FROM categories
  WHERE parent_id IS NULL

  UNION ALL

  SELECT c.id, c.name, c.parent_id, a.nivel + 1, a.ruta || ' > ' || c.name
  FROM categories AS c
  INNER JOIN arbol AS a ON a.id = c.parent_id
)
SELECT id, name, nivel, ruta
FROM arbol
ORDER BY ruta;$c15590$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c15591$arbol-de-categorias$c15591$), $c15592$WITH RECURSIVE arbol(id, name, parent_id, nivel, ruta) AS (SELECT id, name, parent_id, 1, name FROM categories WHERE parent_id IS NULL UNION ALL SELECT c.id, c.name, c.parent_id, a.nivel + 1, a.ruta || ' > ' || c.name FROM categories AS c INNER JOIN arbol AS a ON a.id = c.parent_id WHERE a.nivel < 5) SELECT id, name, nivel, ruta FROM arbol ORDER BY ruta;$c15592$, false, $c15593$Con cota de profundidad explícita$c15593$, 1);

