insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c15706$pedidos-por-pais-y-canal$c15706$), $c15707$SELECT
  c.country,
  count(*) AS total_orders,
  count(*) FILTER (WHERE o.channel = 'app') AS app_orders,
