insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c15879$adopcion-de-la-app-por-pais$c15879$), $c15880$SELECT
  c.country,
  count(DISTINCT o.customer_id) AS buying_customers,
  count(DISTINCT o.customer_id) FILTER (WHERE o.channel = 'app') AS app_customers,
  count(DISTINCT o.customer_id) FILTER (WHERE o.channel = 'web') AS web_customers,
  round(
    100.0 * count(DISTINCT o.customer_id) FILTER (WHERE o.channel = 'app')
      / nullif(count(DISTINCT o.customer_id), 0),
    1
  ) AS app_adoption_pct
FROM orders o
JOIN customers c ON c.id = o.customer_id
WHERE o.status <> 'cancelled'
GROUP BY c.country
ORDER BY app_adoption_pct DESC, c.country;$c15880$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c15881$adopcion-de-la-app-por-pais$c15881$), $c15882$SELECT
