delete from public.exercise_solutions where exercise_id = (select id from public.exercises where slug = $c15992$cuartiles-de-consumo-en-chile$c15992$);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c15993$cuartiles-de-consumo-en-chile$c15993$), $c15994$WITH escuchas AS (
  SELECT p.user_id, count(*) AS reproducciones
  FROM plays AS p
  INNER JOIN users AS u ON u.id = p.user_id
  WHERE u.country = 'CL'
  GROUP BY p.user_id
),
segmentos AS (
  SELECT
    user_id,
    reproducciones,
    ntile(4) OVER (ORDER BY reproducciones DESC, user_id) AS cuartil
  FROM escuchas
)
SELECT
  cuartil,
  count(*) AS oyentes,
  min(reproducciones) AS minimo,
  max(reproducciones) AS maximo,
  round(avg(reproducciones), 2) AS promedio
FROM segmentos
GROUP BY cuartil
ORDER BY cuartil;$c15994$, true, 'reference', 0);

