delete from public.exercise_solutions where exercise_id = (select id from public.exercises where slug = $c16367$desafio-media-movil-con-dias-sin-datos$c16367$);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c16368$desafio-media-movil-con-dias-sin-datos$c16368$), $c16369$WITH calendario AS (
  SELECT generate_series(DATE '2025-07-01', DATE '2025-09-15', INTERVAL '1 day')::date AS dia
),
del_artista AS (
  SELECT
    (p.played_at AT TIME ZONE 'UTC')::date AS dia,
    count(*) AS reproducciones
  FROM plays AS p
  INNER JOIN tracks AS t ON t.id = p.track_id
  INNER JOIN albums AS al ON al.id = t.album_id
  WHERE al.artist_id = 247
    AND p.played_at >= timestamptz '2025-07-01 00:00:00+00'
  GROUP BY 1
),
serie AS (
  SELECT
    c.dia,
    coalesce(a.reproducciones, 0) AS reproducciones
  FROM calendario AS c
  LEFT JOIN del_artista AS a ON a.dia = c.dia
),
con_media AS (
  SELECT
    dia,
    reproducciones,
    round(avg(reproducciones) OVER (
      ORDER BY dia
      ROWS BETWEEN 6 PRECEDING AND CURRENT ROW
    ), 2) AS media_7d
  FROM serie
)
SELECT dia, reproducciones, media_7d
FROM con_media
WHERE dia >= DATE '2025-08-01'
ORDER BY dia;$c16369$, true, 'reference', 0);

