insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c16555$cuentas-solo-emisoras$c16555$), $c16556$WITH solo_emisoras AS (
  SELECT t.from_account_id AS account_id
  FROM transfers AS t
  INNER JOIN accounts AS a ON a.id = t.from_account_id
  WHERE t.status = 'completed'
    AND a.currency = 'CLP'

  EXCEPT

  SELECT t.to_account_id
  FROM transfers AS t
  WHERE t.status = 'completed'
)
SELECT s.account_id, u.full_name, u.city
FROM solo_emisoras AS s
INNER JOIN accounts AS a ON a.id = s.account_id
INNER JOIN users AS u ON u.id = a.user_id
ORDER BY s.account_id;$c16556$, true, 'reference', 0);

