delete from public.exercise_solutions where exercise_id = (select id from public.exercises where slug = $c16673$reproducciones-contra-el-mes-anterior$c16673$);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c16674$reproducciones-contra-el-mes-anterior$c16674$), $c16675$WITH mensual AS (
  SELECT
    date_trunc('month', played_at AT TIME ZONE 'UTC')::date AS mes,
    count(*) AS reproducciones
  FROM plays
  GROUP BY 1
)
SELECT
  mes,
  reproducciones,
  lag(reproducciones) OVER (ORDER BY mes) AS reproducciones_mes_anterior,
  reproducciones - lag(reproducciones) OVER (ORDER BY mes) AS variacion
FROM mensual
ORDER BY mes;$c16675$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c16676$reproducciones-contra-el-mes-anterior$c16676$), $c16677$WITH mensual AS (SELECT date_trunc('month', played_at AT TIME ZONE 'UTC')::date AS mes, count(*) AS reproducciones FROM plays GROUP BY 1), con_anterior AS (SELECT mes, reproducciones, lag(reproducciones) OVER (ORDER BY mes) AS anterior FROM mensual) SELECT mes, reproducciones, anterior AS reproducciones_mes_anterior, reproducciones - anterior AS variacion FROM con_anterior ORDER BY mes;$c16677$, false, $c16678$Segunda CTE para no repetir el lag$c16678$, 1);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c16679$reproducciones-contra-el-mes-anterior$c16679$), $c16680$SELECT mes, reproducciones, lag(reproducciones) OVER (ORDER BY mes) AS reproducciones_mes_anterior, reproducciones - lag(reproducciones) OVER (ORDER BY mes) AS variacion FROM (SELECT date_trunc('month', played_at AT TIME ZONE 'UTC')::date AS mes, count(*) AS reproducciones FROM plays GROUP BY 1) AS mensual ORDER BY mes;$c16680$, false, $c16681$Subconsulta en lugar de CTE$c16681$, 2);

