insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c16716$variacion-porcentual-de-altas$c16716$), $c16717$WITH altas_por_mes AS (
  SELECT
    date_trunc('month', signup_at AT TIME ZONE 'UTC')::date AS mes,
    count(*) AS altas
  FROM users
  GROUP BY 1
),
con_anterior AS (
  SELECT
    mes,
    altas,
    lag(altas) OVER (ORDER BY mes) AS altas_mes_anterior
  FROM altas_por_mes
)
SELECT
  mes,
  altas,
  altas_mes_anterior,
  round(100.0 * (altas - altas_mes_anterior) / nullif(altas_mes_anterior, 0), 1) AS variacion_pct
FROM con_anterior
ORDER BY mes;$c16717$, true, 'reference', 0);

