insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c16758$variacion-mensual-por-pais$c16758$), $c16759$WITH mensual AS (
  SELECT
    u.country,
    date_trunc('month', p.played_at AT TIME ZONE 'UTC')::date AS mes,
    count(*) AS reproducciones
  FROM plays AS p
  INNER JOIN users AS u ON u.id = p.user_id
  GROUP BY 1, 2
)
SELECT
  country,
  mes,
  reproducciones,
  reproducciones - lag(reproducciones) OVER (PARTITION BY country ORDER BY mes) AS variacion
FROM mensual
ORDER BY country, mes;$c16759$, true, 'reference', 0);

