insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c16839$dias-hasta-el-siguiente-album$c16839$), $c16840$SELECT
  ar.name AS artista,
  al.title AS album,
  al.released_on,
  lead(al.released_on) OVER (PARTITION BY ar.id ORDER BY al.released_on) AS siguiente_lanzamiento,
  lead(al.released_on) OVER (PARTITION BY ar.id ORDER BY al.released_on) - al.released_on AS dias_hasta_siguiente
FROM albums AS al
INNER JOIN artists AS ar ON ar.id = al.artist_id
WHERE ar.genre = 'cumbia'
ORDER BY artista, al.released_on;$c16840$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c16841$dias-hasta-el-siguiente-album$c16841$), $c16842$WITH lanzamientos AS (SELECT ar.name AS artista, al.title AS album, al.released_on, lead(al.released_on) OVER (PARTITION BY ar.id ORDER BY al.released_on) AS siguiente FROM albums AS al INNER JOIN artists AS ar ON ar.id = al.artist_id WHERE ar.genre = 'cumbia') SELECT artista, album, released_on, siguiente AS siguiente_lanzamiento, siguiente - released_on AS dias_hasta_siguiente FROM lanzamientos ORDER BY artista, released_on;$c16842$, false, $c16843$CTE con el siguiente lanzamiento$c16843$, 1);

