insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c16882$indice-contra-el-ultimo-mes$c16882$), $c16883$WITH mensual AS (
  SELECT
    u.country,
    date_trunc('month', p.played_at AT TIME ZONE 'UTC')::date AS mes,
    count(*) AS reproducciones
  FROM plays AS p
  INNER JOIN users AS u ON u.id = p.user_id
  WHERE p.played_at < timestamptz '2025-09-01 00:00:00+00'
  GROUP BY 1, 2
),
con_base AS (
  SELECT
    country,
    mes,
    reproducciones,
    last_value(reproducciones) OVER (
      PARTITION BY country
      ORDER BY mes
      ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING
    ) AS reproducciones_ultimo_mes
  FROM mensual
)
SELECT
  country,
  mes,
  reproducciones,
  reproducciones_ultimo_mes,
  round(100.0 * reproducciones / reproducciones_ultimo_mes, 1) AS indice_vs_ultimo_mes
FROM con_base
ORDER BY country, mes;$c16883$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c16884$indice-contra-el-ultimo-mes$c16884$), $c16885$WITH mensual AS (SELECT u.country, date_trunc('month', p.played_at AT TIME ZONE 'UTC')::date AS mes, count(*) AS reproducciones FROM plays AS p INNER JOIN users AS u ON u.id = p.user_id WHERE p.played_at < timestamptz '2025-09-01 00:00:00+00' GROUP BY 1, 2), con_base AS (SELECT country, mes, reproducciones, first_value(reproducciones) OVER (PARTITION BY country ORDER BY mes DESC) AS reproducciones_ultimo_mes FROM mensual) SELECT country, mes, reproducciones, reproducciones_ultimo_mes, round(100.0 * reproducciones / reproducciones_ultimo_mes, 1) AS indice_vs_ultimo_mes FROM con_base ORDER BY country, mes;$c16885$, false, $c16886$first_value con orden descendente$c16886$, 1);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c16887$indice-contra-el-ultimo-mes$c16887$), $c16888$WITH mensual AS (SELECT u.country, date_trunc('month', p.played_at AT TIME ZONE 'UTC')::date AS mes, count(*) AS reproducciones FROM plays AS p INNER JOIN users AS u ON u.id = p.user_id WHERE p.played_at < timestamptz '2025-09-01 00:00:00+00' GROUP BY 1, 2), con_base AS (SELECT country, mes, reproducciones, nth_value(reproducciones, 1) OVER (PARTITION BY country ORDER BY mes DESC ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS reproducciones_ultimo_mes FROM mensual) SELECT country, mes, reproducciones, reproducciones_ultimo_mes, round(100.0 * reproducciones / reproducciones_ultimo_mes, 1) AS indice_vs_ultimo_mes FROM con_base ORDER BY country, mes;$c16888$, false, $c16889$nth_value desde el final$c16889$, 2);

