delete from public.exercise_solutions where exercise_id = (select id from public.exercises where slug = $c16924$sesiones-de-escucha-por-mes$c16924$);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c16925$sesiones-de-escucha-por-mes$c16925$), $c16926$WITH marcadas AS (
  SELECT
    played_at,
    lag(played_at) OVER (PARTITION BY user_id ORDER BY played_at) AS anterior
  FROM plays
),
clasificadas AS (
  SELECT
    date_trunc('month', played_at AT TIME ZONE 'UTC')::date AS mes,
    CASE
      WHEN anterior IS NULL OR played_at - anterior > interval '30 minutes' THEN 1
      ELSE 0
    END AS inicia_sesion
  FROM marcadas
)
SELECT
  mes,
  count(*) AS reproducciones,
  sum(inicia_sesion) AS sesiones,
  round(count(*)::numeric / sum(inicia_sesion), 2) AS reproducciones_por_sesion
FROM clasificadas
GROUP BY mes
ORDER BY mes;$c16926$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c16927$sesiones-de-escucha-por-mes$c16927$), $c16928$WITH marcadas AS (SELECT played_at, lag(played_at) OVER (PARTITION BY user_id ORDER BY played_at) AS anterior FROM plays), clasificadas AS (SELECT date_trunc('month', played_at AT TIME ZONE 'UTC')::date AS mes, (anterior IS NULL OR played_at - anterior > interval '30 minutes') AS inicia_sesion FROM marcadas) SELECT mes, count(*) AS reproducciones, count(*) FILTER (WHERE inicia_sesion) AS sesiones, round(count(*)::numeric / count(*) FILTER (WHERE inicia_sesion), 2) AS reproducciones_por_sesion FROM clasificadas GROUP BY mes ORDER BY mes;$c16928$, false, $c16929$Bandera booleana con FILTER$c16929$, 1);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c16930$sesiones-de-escucha-por-mes$c16930$), $c16931$WITH marcadas AS (SELECT played_at, lag(played_at) OVER (PARTITION BY user_id ORDER BY played_at) AS anterior FROM plays), clasificadas AS (SELECT date_trunc('month', played_at AT TIME ZONE 'UTC')::date AS mes, CASE WHEN anterior IS NULL OR extract(epoch FROM played_at - anterior) > 1800 THEN 1 ELSE 0 END AS inicia_sesion FROM marcadas) SELECT mes, count(*) AS reproducciones, sum(inicia_sesion) AS sesiones, round(count(*)::numeric / sum(inicia_sesion), 2) AS reproducciones_por_sesion FROM clasificadas GROUP BY mes ORDER BY mes;$c16931$, false, $c16932$Comparando segundos en lugar de intervalos$c16932$, 2);

