insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c16967$tamano-de-cada-cohorte$c16967$), $c16968$SELECT date_trunc('month', signup_at AT TIME ZONE 'UTC')::date AS cohorte, count(*) AS usuarios, round(100.0 * count(*) / (SELECT count(*) FROM users), 2) AS pct_del_total FROM users GROUP BY 1 ORDER BY 1;$c16968$, false, $c16969$Total con subconsulta escalar$c16969$, 1);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c16970$tamano-de-cada-cohorte$c16970$), $c16971$WITH total AS (SELECT count(*) AS n FROM users) SELECT date_trunc('month', u.signup_at AT TIME ZONE 'UTC')::date AS cohorte, count(*) AS usuarios, round(100.0 * count(*) / t.n, 2) AS pct_del_total FROM users AS u CROSS JOIN total AS t GROUP BY 1, t.n ORDER BY 1;$c16971$, false, $c16972$Total en una CTE$c16972$, 2);

