insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17008$activacion-en-los-primeros-siete-dias$c17008$), $c17009$WITH cohortes AS (SELECT id, signup_at, date_trunc('month', signup_at AT TIME ZONE 'UTC')::date AS cohorte FROM users WHERE signup_at < timestamptz '2025-09-01 00:00:00+00'), activados AS (SELECT c.id FROM cohortes AS c WHERE EXISTS (SELECT 1 FROM plays AS p WHERE p.user_id = c.id AND p.played_at < c.signup_at + INTERVAL '7 days')) SELECT c.cohorte, count(*) AS usuarios, count(a.id) AS activados, round(100.0 * count(a.id) / count(*), 2) AS tasa_activacion_pct FROM cohortes AS c LEFT JOIN activados AS a ON a.id = c.id GROUP BY 1 ORDER BY 1;$c17009$, false, $c17010$Con EXISTS$c17010$, 1);

