FROM actividad AS a
INNER JOIN tamano AS t ON t.cohorte = a.cohorte
GROUP BY a.cohorte, 2, t.usuarios_cohorte
ORDER BY a.cohorte, 2;$c17087$, true, 'reference', 0);

