insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17202$retencion-del-mes-1-por-pais$c17202$), $c17203$WITH cohortes AS (
  SELECT
    id,
    country,
    date_trunc('month', signup_at AT TIME ZONE 'UTC')::date AS cohorte
  FROM users
  WHERE signup_at < timestamptz '2025-08-01 00:00:00+00'
),
activos_m1 AS (
  SELECT DISTINCT c.id
  FROM cohortes AS c
  INNER JOIN plays AS p ON p.user_id = c.id
  WHERE date_trunc('month', p.played_at AT TIME ZONE 'UTC')::date
        = (c.cohorte + INTERVAL '1 month')::date
)
SELECT
  c.country,
  count(*) AS usuarios,
  count(a.id) AS retenidos_m1,
  round(100.0 * count(a.id) / count(*), 2) AS retencion_m1_pct
FROM cohortes AS c
LEFT JOIN activos_m1 AS a ON a.id = c.id
GROUP BY c.country
ORDER BY 4 DESC, 1;$c17203$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17204$retencion-del-mes-1-por-pais$c17204$), $c17205$WITH cohortes AS (SELECT id, country, date_trunc('month', signup_at AT TIME ZONE 'UTC')::date AS cohorte FROM users WHERE signup_at < timestamptz '2025-08-01 00:00:00+00'), activos_m1 AS (SELECT DISTINCT c.id FROM cohortes AS c INNER JOIN plays AS p ON p.user_id = c.id WHERE (12 * (date_part('year', date_trunc('month', p.played_at AT TIME ZONE 'UTC')::date) - date_part('year', c.cohorte)) + (date_part('month', date_trunc('month', p.played_at AT TIME ZONE 'UTC')::date) - date_part('month', c.cohorte)))::int = 1) SELECT c.country, count(*) AS usuarios, count(a.id) AS retenidos_m1, round(100.0 * count(a.id) / count(*), 2) AS retencion_m1_pct FROM cohortes AS c LEFT JOIN activos_m1 AS a ON a.id = c.id GROUP BY c.country ORDER BY 4 DESC, 1;$c17205$, false, $c17206$Índice de mes en lugar de suma de intervalo$c17206$, 1);

