insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17240$funnel-pasos-de-pedidos$c17240$), $c17241$SELECT
  CASE event
    WHEN 'placed' THEN 1
    WHEN 'accepted' THEN 2
    WHEN 'preparing' THEN 3
    WHEN 'picked_up' THEN 4
    WHEN 'delivered' THEN 5
