insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17242$funnel-pasos-de-pedidos$c17242$), $c17243$SELECT CASE event WHEN 'placed' THEN 1 WHEN 'accepted' THEN 2 WHEN 'preparing' THEN 3 WHEN 'picked_up' THEN 4 WHEN 'delivered' THEN 5 END AS paso, event AS etapa, count(DISTINCT order_id) AS pedidos FROM order_events WHERE event IN ('placed', 'accepted', 'preparing', 'picked_up', 'delivered') GROUP BY 1, 2 ORDER BY paso;$c17243$, false, $c17244$Filtro por lista de eventos del funnel$c17244$, 1);

