insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17281$funnel-conversion-paso-a-paso$c17281$), $c17282$WITH por_paso AS (
  SELECT
    CASE event
      WHEN 'placed' THEN 1
      WHEN 'accepted' THEN 2
      WHEN 'preparing' THEN 3
      WHEN 'picked_up' THEN 4
      WHEN 'delivered' THEN 5
    END AS paso,
    event AS etapa,
    count(DISTINCT order_id) AS pedidos
  FROM order_events
  WHERE event <> 'cancelled'
  GROUP BY 1, 2
)
SELECT
  paso,
  etapa,
  pedidos,
  round(100.0 * pedidos / lag(pedidos) OVER (ORDER BY paso), 2) AS pct_vs_anterior,
  round(100.0 * pedidos / first_value(pedidos) OVER (ORDER BY paso), 2) AS pct_vs_inicio
FROM por_paso
ORDER BY paso;$c17282$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17283$funnel-conversion-paso-a-paso$c17283$), $c17284$WITH por_paso AS (SELECT CASE event WHEN 'placed' THEN 1 WHEN 'accepted' THEN 2 WHEN 'preparing' THEN 3 WHEN 'picked_up' THEN 4 WHEN 'delivered' THEN 5 END AS paso, event AS etapa, count(DISTINCT order_id) AS pedidos FROM order_events WHERE event <> 'cancelled' GROUP BY 1, 2) SELECT paso, etapa, pedidos, round(100.0 * pedidos / lag(pedidos) OVER (ORDER BY paso), 2) AS pct_vs_anterior, round(100.0 * pedidos / (SELECT p.pedidos FROM por_paso AS p WHERE p.paso = 1), 2) AS pct_vs_inicio FROM por_paso ORDER BY paso;$c17284$, false, $c17285$El total del paso 1 con una subconsulta escalar$c17285$, 1);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17286$funnel-conversion-paso-a-paso$c17286$), $c17287$WITH por_paso AS (SELECT CASE event WHEN 'placed' THEN 1 WHEN 'accepted' THEN 2 WHEN 'preparing' THEN 3 WHEN 'picked_up' THEN 4 WHEN 'delivered' THEN 5 END AS paso, event AS etapa, count(DISTINCT order_id) AS pedidos FROM order_events WHERE event <> 'cancelled' GROUP BY 1, 2) SELECT paso, etapa, pedidos, round(100.0 * pedidos / lag(pedidos, 1) OVER (ORDER BY paso), 2) AS pct_vs_anterior, round(100.0 * pedidos / first_value(pedidos) OVER (ORDER BY paso ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), 2) AS pct_vs_inicio FROM por_paso ORDER BY paso;$c17287$, false, $c17288$Marco explícito en las dos ventanas$c17288$, 2);

