insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17372$funnel-por-canal-de-venta$c17372$), $c17373$WITH hitos AS (SELECT o.id AS order_id, o.channel, min(pay.paid_at) AS pagado_at, min(shp.delivered_at) AS entregado_at FROM orders AS o LEFT JOIN payments AS pay ON pay.order_id = o.id AND pay.status IN ('approved', 'refunded') LEFT JOIN shipments AS shp ON shp.order_id = o.id GROUP BY o.id, o.channel), conteos AS (SELECT channel AS canal, count(*) AS pedidos, count(pagado_at) AS pagados, count(entregado_at) AS entregados FROM hitos GROUP BY channel) SELECT canal, pedidos, pagados, entregados, round(100.0 * pagados / pedidos, 2) AS pct_pago, round(100.0 * entregados / nullif(pagados, 0), 2) AS pct_entrega_sobre_pago FROM conteos ORDER BY canal;$c17373$, false, $c17374$Conteos en una CTE y tasas afuera$c17374$, 2);

