SELECT
  ultimo_paso,
  CASE ultimo_paso WHEN 1 THEN 'placed' /* ... */ END AS ultima_etapa,
  count(*) AS pedidos,
  round(100.0 * count(*) / ___(count(*)) ___ (), 2) AS pct_del_total
FROM avance
GROUP BY 1, 2
ORDER BY ultimo_paso;
```$c17421$, 2, 10)
