insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17453$funnel-activacion-orden-estricto$c17453$), $c17454$WITH escuchas AS (
  SELECT user_id, min(played_at) AS primera_escucha_at
  FROM plays
  GROUP BY user_id
), listas AS (
  SELECT user_id, min(created_at) AS primera_playlist_at
  FROM playlists
  GROUP BY user_id
), subs AS (
  SELECT user_id, min(started_on) AS primera_suscripcion_on
  FROM subscriptions
  GROUP BY user_id
), hitos AS (
  SELECT
    u.id AS user_id,
    u.signup_at,
    e.primera_escucha_at,
    l.primera_playlist_at,
    s.primera_suscripcion_on
  FROM users AS u
  LEFT JOIN escuchas AS e ON e.user_id = u.id
  LEFT JOIN listas AS l ON l.user_id = u.id
  LEFT JOIN subs AS s ON s.user_id = u.id
)
SELECT 1 AS paso, 'alta' AS etapa, count(*) AS usuarios_cualquier_orden, count(*) AS usuarios_orden_estricto
FROM hitos
UNION ALL
SELECT 2, 'primera escucha', count(primera_escucha_at),
  count(*) FILTER (WHERE primera_escucha_at > signup_at)
FROM hitos
UNION ALL
SELECT 3, 'primera playlist', count(primera_playlist_at),
  count(*) FILTER (
    WHERE primera_escucha_at > signup_at
      AND primera_playlist_at > primera_escucha_at
  )
FROM hitos
UNION ALL
SELECT 4, 'primera suscripcion', count(primera_suscripcion_on),
  count(*) FILTER (
    WHERE primera_escucha_at > signup_at
      AND primera_playlist_at > primera_escucha_at
      AND primera_suscripcion_on >= (primera_playlist_at AT TIME ZONE 'UTC')::date
  )
FROM hitos
ORDER BY paso;$c17454$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17455$funnel-activacion-orden-estricto$c17455$), $c17456$WITH hitos AS (SELECT u.id AS user_id, u.signup_at, (SELECT min(p.played_at) FROM plays AS p WHERE p.user_id = u.id) AS primera_escucha_at, (SELECT min(pl.created_at) FROM playlists AS pl WHERE pl.user_id = u.id) AS primera_playlist_at, (SELECT min(s.started_on) FROM subscriptions AS s WHERE s.user_id = u.id) AS primera_suscripcion_on FROM users AS u) SELECT 1 AS paso, 'alta' AS etapa, count(*) AS usuarios_cualquier_orden, count(*) AS usuarios_orden_estricto FROM hitos UNION ALL SELECT 2, 'primera escucha', count(primera_escucha_at), count(*) FILTER (WHERE primera_escucha_at > signup_at) FROM hitos UNION ALL SELECT 3, 'primera playlist', count(primera_playlist_at), count(*) FILTER (WHERE primera_escucha_at > signup_at AND primera_playlist_at > primera_escucha_at) FROM hitos UNION ALL SELECT 4, 'primera suscripcion', count(primera_suscripcion_on), count(*) FILTER (WHERE primera_escucha_at > signup_at AND primera_playlist_at > primera_escucha_at AND primera_suscripcion_on >= (primera_playlist_at AT TIME ZONE 'UTC')::date) FROM hitos ORDER BY paso;$c17456$, false, $c17457$Hitos con subconsultas escalares$c17457$, 1);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17458$funnel-activacion-orden-estricto$c17458$), $c17459$WITH escuchas AS (SELECT user_id, min(played_at) AS primera_escucha_at FROM plays GROUP BY user_id), listas AS (SELECT user_id, min(created_at) AS primera_playlist_at FROM playlists GROUP BY user_id), subs AS (SELECT user_id, min(started_on) AS primera_suscripcion_on FROM subscriptions GROUP BY user_id), hitos AS (SELECT u.id AS user_id, u.signup_at, e.primera_escucha_at, l.primera_playlist_at, s.primera_suscripcion_on FROM users AS u LEFT JOIN escuchas AS e ON e.user_id = u.id LEFT JOIN listas AS l ON l.user_id = u.id LEFT JOIN subs AS s ON s.user_id = u.id), marcas AS (SELECT primera_escucha_at, primera_playlist_at, primera_suscripcion_on, (primera_escucha_at > signup_at) AS e2, (primera_escucha_at > signup_at AND primera_playlist_at > primera_escucha_at) AS e3, (primera_escucha_at > signup_at AND primera_playlist_at > primera_escucha_at AND primera_suscripcion_on >= (primera_playlist_at AT TIME ZONE 'UTC')::date) AS e4 FROM hitos) SELECT 1 AS paso, 'alta' AS etapa, count(*) AS usuarios_cualquier_orden, count(*) AS usuarios_orden_estricto FROM marcas UNION ALL SELECT 2, 'primera escucha', count(primera_escucha_at), count(*) FILTER (WHERE e2) FROM marcas UNION ALL SELECT 3, 'primera playlist', count(primera_playlist_at), count(*) FILTER (WHERE e3) FROM marcas UNION ALL SELECT 4, 'primera suscripcion', count(primera_suscripcion_on), count(*) FILTER (WHERE e4) FROM marcas ORDER BY paso;$c17459$, false, $c17460$Marca de paso estricto precalculada con CASE$c17460$, 2);

