delete from public.exercise_solutions where exercise_id = (select id from public.exercises where slug = $c17497$funnel-tiempo-hasta-convertir-por-ciudad$c17497$);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17498$funnel-tiempo-hasta-convertir-por-ciudad$c17498$), $c17499$WITH hitos AS (
  SELECT
    oe.order_id,
    min(oe.event_at) FILTER (WHERE oe.event = 'placed') AS placed_at,
    min(oe.event_at) FILTER (WHERE oe.event = 'accepted') AS accepted_at,
    min(oe.event_at) FILTER (WHERE oe.event = 'delivered') AS delivered_at
  FROM order_events AS oe
  GROUP BY oe.order_id
)
SELECT
  c.name AS ciudad,
  count(*) AS pedidos_entregados,
  round(avg(extract(epoch FROM h.accepted_at - h.placed_at) / 60), 2) AS min_prom_aceptacion,
  round(
    percentile_cont(0.5) WITHIN GROUP (
      ORDER BY extract(epoch FROM h.delivered_at - h.placed_at) / 60
    )::numeric,
    2
  ) AS min_mediana_entrega
FROM hitos AS h
INNER JOIN orders AS o ON o.id = h.order_id
INNER JOIN restaurants AS r ON r.id = o.restaurant_id
INNER JOIN cities AS c ON c.id = r.city_id
WHERE h.delivered_at IS NOT NULL
GROUP BY c.name
ORDER BY min_mediana_entrega DESC, ciudad;$c17499$, true, 'reference', 0);

