insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17613$dedup-impacto-por-pais$c17613$), $c17614$SELECT
  u.country,
  count(*) AS reproducciones_crudas,
  count(DISTINCT (p.user_id, p.track_id, p.played_at)) AS reproducciones_unicas,
  count(*) - count(DISTINCT (p.user_id, p.track_id, p.played_at)) AS filas_sobrantes
FROM plays AS p
INNER JOIN users AS u ON u.id = p.user_id
GROUP BY u.country
ORDER BY filas_sobrantes DESC;$c17614$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17615$dedup-impacto-por-pais$c17615$), $c17616$WITH crudas AS (
  SELECT u.country, count(*) AS n
  FROM plays AS p
  INNER JOIN users AS u ON u.id = p.user_id
  GROUP BY u.country
),
unicas AS (
  SELECT u.country, count(*) AS n
  FROM (SELECT DISTINCT user_id, track_id, played_at FROM plays) AS d
  INNER JOIN users AS u ON u.id = d.user_id
  GROUP BY u.country
)
SELECT
  c.country,
  c.n AS reproducciones_crudas,
  x.n AS reproducciones_unicas,
  c.n - x.n AS filas_sobrantes
FROM crudas AS c
INNER JOIN unicas AS x ON x.country = c.country
ORDER BY filas_sobrantes DESC;$c17616$, false, $c17617$Dos CTE: una con las filas crudas y otra con las únicas$c17617$, 1);

