insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17730$dedup-ultimo-intento-de-pago$c17730$), $c17731$SELECT DISTINCT ON (p.order_id)
  p.order_id,
  p.id AS payment_id,
  p.status,
  p.method,
  p.amount
FROM payments AS p
INNER JOIN orders AS o ON o.id = p.order_id
