insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17732$dedup-ultimo-intento-de-pago$c17732$), $c17733$WITH intentos AS (
  SELECT
    p.order_id,
    p.id AS payment_id,
    p.status,
    p.method,
    p.amount,
    row_number() OVER (PARTITION BY p.order_id ORDER BY p.id DESC) AS puesto
  FROM payments AS p
  INNER JOIN orders AS o ON o.id = p.order_id
  INNER JOIN customers AS c ON c.id = o.customer_id
  WHERE c.country = 'UY'
)
SELECT order_id, payment_id, status, method, amount
FROM intentos
WHERE puesto = 1
ORDER BY order_id;$c17733$, false, $c17734$Con ROW_NUMBER, portable a otros motores$c17734$, 1);

