delete from public.exercise_solutions where exercise_id = (select id from public.exercises where slug = $c17769$dedup-cuenta-ganadora-por-correo$c17769$);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17770$dedup-cuenta-ganadora-por-correo$c17770$), $c17771$WITH duplicados AS (
  SELECT lower(btrim(email)) AS correo
  FROM customers
  GROUP BY lower(btrim(email))
  HAVING count(*) > 1
),
candidatas AS (
  SELECT
    lower(btrim(c.email)) AS correo,
    c.id,
    c.signup_at,
    count(o.id) AS pedidos
  FROM customers AS c
  INNER JOIN duplicados AS d ON d.correo = lower(btrim(c.email))
  LEFT JOIN orders AS o ON o.customer_id = c.id
  GROUP BY lower(btrim(c.email)), c.id, c.signup_at
),
elegidas AS (
  SELECT
    correo,
    id,
    pedidos,
    count(*) OVER (PARTITION BY correo) AS cuentas,
    sum(pedidos) OVER (PARTITION BY correo) AS pedidos_grupo,
    row_number() OVER (PARTITION BY correo ORDER BY pedidos DESC, signup_at, id) AS puesto
  FROM candidatas
)
SELECT
  correo,
  cuentas,
  id AS id_ganador,
  pedidos AS pedidos_ganador,
  pedidos_grupo
FROM elegidas
WHERE puesto = 1
ORDER BY correo;$c17771$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17772$dedup-cuenta-ganadora-por-correo$c17772$), $c17773$WITH candidatas AS (
  SELECT
    lower(btrim(c.email)) AS correo,
    c.id,
    c.signup_at,
    (SELECT count(*) FROM orders AS o WHERE o.customer_id = c.id) AS pedidos
  FROM customers AS c
  WHERE lower(btrim(c.email)) IN (
    SELECT lower(btrim(email)) FROM customers GROUP BY lower(btrim(email)) HAVING count(*) > 1
  )
),
totales AS (
  SELECT correo, count(*) AS cuentas, sum(pedidos) AS pedidos_grupo
  FROM candidatas
  GROUP BY correo
),
ganadoras AS (
  SELECT DISTINCT ON (correo) correo, id, pedidos
  FROM candidatas
  ORDER BY correo, pedidos DESC, signup_at, id
)
SELECT
  g.correo,
  t.cuentas,
  g.id AS id_ganador,
  g.pedidos AS pedidos_ganador,
  t.pedidos_grupo
FROM ganadoras AS g
INNER JOIN totales AS t ON t.correo = g.correo
