insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17893$chequeos-de-validez-en-reproducciones$c17893$), $c17894$SELECT
  count(*) AS checked_rows,
  count(*) FILTER (WHERE p.seconds_played IS NULL) AS null_seconds,
  count(*) FILTER (WHERE p.seconds_played < 0) AS negative_seconds,
  count(*) FILTER (WHERE p.seconds_played > t.duration_seconds) AS over_duration,
  round(
    100.0 * count(*) FILTER (
      WHERE p.seconds_played IS NULL
         OR p.seconds_played < 0
         OR p.seconds_played > t.duration_seconds
    ) / count(*),
    2
  ) AS invalid_pct
FROM plays p
JOIN tracks t ON t.id = p.track_id;$c17894$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c17895$chequeos-de-validez-en-reproducciones$c17895$), $c17896$SELECT
  count(*) AS checked_rows,
  sum(CASE WHEN p.seconds_played IS NULL THEN 1 ELSE 0 END) AS null_seconds,
  sum(CASE WHEN p.seconds_played < 0 THEN 1 ELSE 0 END) AS negative_seconds,
  sum(CASE WHEN p.seconds_played > t.duration_seconds THEN 1 ELSE 0 END) AS over_duration,
  round(
    100.0 * sum(
      CASE
        WHEN p.seconds_played IS NULL THEN 1
        WHEN p.seconds_played < 0 THEN 1
        WHEN p.seconds_played > t.duration_seconds THEN 1
        ELSE 0
      END
    ) / count(*),
    2
  ) AS invalid_pct
FROM plays p
JOIN tracks t ON t.id = p.track_id;$c17896$, false, $c17897$CASE dentro de los agregados (portable a otros motores)$c17897$, 1);

