insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18018$pedidos-sin-items-en-pidelo$c18018$), $c18019$SELECT
  o.id AS order_id,
  o.status,
  o.placed_at AT TIME ZONE 'UTC' AS placed_at_utc,
  r.name AS restaurant_name,
  o.total AS order_total
