ORDER BY placed_at_utc, order_id;$c18019$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18020$pedidos-sin-items-en-pidelo$c18020$), $c18021$SELECT
