ORDER BY o.placed_at, o.id;$c18021$, false, $c18022$LEFT JOIN con la condición IS NULL en el WHERE$c18022$, 1);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18023$pedidos-sin-items-en-pidelo$c18023$), $c18024$SELECT
