insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18148$cobertura-de-clientes-por-ciudad$c18148$), $c18149$WITH con_entrega AS (SELECT DISTINCT customer_id FROM orders WHERE status = 'delivered') SELECT c.country, c.city, count(*) AS clientes, count(e.customer_id) AS clientes_con_entrega, round(100.0 * count(e.customer_id) / count(*), 2) AS cobertura_pct FROM customers AS c LEFT JOIN con_entrega AS e ON e.customer_id = c.id GROUP BY c.country, c.city ORDER BY c.country, c.city;$c18149$, false, $c18150$Conjunto de clientes con entrega en una CTE$c18150$, 1);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18151$cobertura-de-clientes-por-ciudad$c18151$), $c18152$WITH marcados AS (SELECT c.country, c.city, c.id, CASE WHEN EXISTS (SELECT 1 FROM orders AS o WHERE o.customer_id = c.id AND o.status = 'delivered') THEN 1 ELSE 0 END AS tiene FROM customers AS c) SELECT country, city, count(*) AS clientes, sum(tiene)::bigint AS clientes_con_entrega, round(100.0 * sum(tiene) / count(*), 2) AS cobertura_pct FROM marcados GROUP BY country, city ORDER BY country, city;$c18152$, false, $c18153$Marca por cliente con EXISTS$c18153$, 2);

