insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18230$ticket-promedio-al-grano-correcto$c18230$), $c18231$WITH por_pedido AS (
  SELECT
    o.id,
    c.country,
