insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18235$ticket-promedio-al-grano-correcto$c18235$), $c18236$WITH por_pedido AS (SELECT o.id, c.country, o.channel, o.total_amount, (SELECT count(*) FROM order_items AS oi WHERE oi.order_id = o.id) AS lineas FROM orders AS o INNER JOIN customers AS c ON c.id = o.customer_id WHERE o.status = 'delivered') SELECT country, channel, count(*) AS pedidos, round(avg(total_amount), 2) AS ticket_promedio, round(avg(lineas), 3) AS lineas_por_pedido FROM por_pedido WHERE lineas > 0 GROUP BY country, channel ORDER BY country, channel;$c18236$, false, $c18237$Líneas con una subconsulta correlacionada$c18237$, 2);

