insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18270$tiempo-de-entrega-sin-contaminar$c18270$), $c18271$SELECT
  s.carrier,
  count(*) AS envios,
  count(s.delivered_at) AS entregados,
  count(*) - count(s.delivered_at) AS sin_entregar,
  round(avg(EXTRACT(epoch FROM (s.delivered_at - s.shipped_at)) / 3600.0)::numeric, 2) AS horas_promedio
FROM shipments AS s
GROUP BY s.carrier
ORDER BY s.carrier;$c18271$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18272$tiempo-de-entrega-sin-contaminar$c18272$), $c18273$SELECT s.carrier, count(*) AS envios, count(*) FILTER (WHERE s.delivered_at IS NOT NULL) AS entregados, count(*) FILTER (WHERE s.delivered_at IS NULL) AS sin_entregar, round(avg(EXTRACT(epoch FROM (s.delivered_at - s.shipped_at)) / 3600.0) FILTER (WHERE s.delivered_at IS NOT NULL)::numeric, 2) AS horas_promedio FROM shipments AS s GROUP BY s.carrier ORDER BY s.carrier;$c18273$, false, $c18274$Con FILTER explícito$c18274$, 1);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18275$tiempo-de-entrega-sin-contaminar$c18275$), $c18276$SELECT s.carrier, count(*) AS envios, count(s.delivered_at) AS entregados, count(*) - count(s.delivered_at) AS sin_entregar, round((sum(EXTRACT(epoch FROM (s.delivered_at - s.shipped_at)) / 3600.0) / nullif(count(s.delivered_at), 0))::numeric, 2) AS horas_promedio FROM shipments AS s GROUP BY s.carrier ORDER BY s.carrier;$c18276$, false, $c18277$Suma dividida por los entregados$c18277$, 2);

