delete from public.exercise_solutions where exercise_id = (select id from public.exercises where slug = $c18357$tasa-de-devolucion-por-categoria$c18357$);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18358$tasa-de-devolucion-por-categoria$c18358$), $c18359$WITH pedido_categoria AS (
  SELECT DISTINCT
    p.category_id,
    o.id AS order_id,
    (o.status = 'returned') AS devuelto
  FROM orders AS o
  INNER JOIN order_items AS oi ON oi.order_id = o.id
  INNER JOIN products AS p ON p.id = oi.product_id
  WHERE o.status IN ('delivered', 'returned')
)
SELECT
  c.name AS categoria,
  count(*) AS pedidos,
  count(*) FILTER (WHERE pc.devuelto) AS devueltos,
  round(100.0 * count(*) FILTER (WHERE pc.devuelto) / count(*), 2) AS tasa_pct
FROM pedido_categoria AS pc
INNER JOIN categories AS c ON c.id = pc.category_id
GROUP BY c.name
ORDER BY tasa_pct DESC, categoria ASC;$c18359$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18360$tasa-de-devolucion-por-categoria$c18360$), $c18361$WITH pedido_categoria AS (SELECT p.category_id, o.id AS order_id, max(CASE WHEN o.status = 'returned' THEN 1 ELSE 0 END) AS devuelto FROM orders AS o INNER JOIN order_items AS oi ON oi.order_id = o.id INNER JOIN products AS p ON p.id = oi.product_id WHERE o.status IN ('delivered', 'returned') GROUP BY p.category_id, o.id) SELECT c.name AS categoria, count(*) AS pedidos, sum(pc.devuelto)::bigint AS devueltos, round(100.0 * sum(pc.devuelto) / count(*), 2) AS tasa_pct FROM pedido_categoria AS pc INNER JOIN categories AS c ON c.id = pc.category_id GROUP BY c.name ORDER BY tasa_pct DESC, categoria ASC;$c18361$, false, $c18362$Desduplicado con GROUP BY en lugar de DISTINCT$c18362$, 1);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18363$tasa-de-devolucion-por-categoria$c18363$), $c18364$SELECT c.name AS categoria, count(DISTINCT o.id) AS pedidos, count(DISTINCT o.id) FILTER (WHERE o.status = 'returned') AS devueltos, round(100.0 * count(DISTINCT o.id) FILTER (WHERE o.status = 'returned') / count(DISTINCT o.id), 2) AS tasa_pct FROM orders AS o INNER JOIN order_items AS oi ON oi.order_id = o.id INNER JOIN products AS p ON p.id = oi.product_id INNER JOIN categories AS c ON c.id = p.category_id WHERE o.status IN ('delivered', 'returned') GROUP BY c.name ORDER BY tasa_pct DESC, categoria ASC;$c18364$, false, $c18365$Conteos distintos sobre el join completo$c18365$, 2);

