insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18399$caida-de-ventas-mexico-por-canal$c18399$), $c18400$SELECT
  o.channel AS canal,
  count(*) FILTER (WHERE o.created_at < timestamptz '2025-08-01 00:00:00+00') AS pedidos_julio,
  count(*) FILTER (WHERE o.created_at >= timestamptz '2025-08-01 00:00:00+00') AS pedidos_agosto,
  round(sum(o.total_amount) FILTER (WHERE o.created_at < timestamptz '2025-08-01 00:00:00+00'), 2) AS ingresos_julio,
  round(sum(o.total_amount) FILTER (WHERE o.created_at >= timestamptz '2025-08-01 00:00:00+00'), 2) AS ingresos_agosto,
  round(
    100.0 * (
      sum(o.total_amount) FILTER (WHERE o.created_at >= timestamptz '2025-08-01 00:00:00+00')
      - sum(o.total_amount) FILTER (WHERE o.created_at < timestamptz '2025-08-01 00:00:00+00')
    ) / sum(o.total_amount) FILTER (WHERE o.created_at < timestamptz '2025-08-01 00:00:00+00'),
    2
  ) AS variacion_pct
FROM orders AS o
INNER JOIN customers AS c ON c.id = o.customer_id
WHERE c.country = 'MX'
  AND o.status = 'delivered'
  AND o.created_at >= timestamptz '2025-07-01 00:00:00+00'
  AND o.created_at <  timestamptz '2025-09-01 00:00:00+00'
GROUP BY o.channel
ORDER BY o.channel;$c18400$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18401$caida-de-ventas-mexico-por-canal$c18401$), $c18402$WITH base AS (SELECT o.channel, o.total_amount, CASE WHEN o.created_at < timestamptz '2025-08-01 00:00:00+00' THEN 'jul' ELSE 'ago' END AS periodo FROM orders AS o INNER JOIN customers AS c ON c.id = o.customer_id WHERE c.country = 'MX' AND o.status = 'delivered' AND o.created_at >= timestamptz '2025-07-01 00:00:00+00' AND o.created_at < timestamptz '2025-09-01 00:00:00+00'), agrupado AS (SELECT channel AS canal, count(CASE WHEN periodo = 'jul' THEN 1 END) AS pedidos_julio, count(CASE WHEN periodo = 'ago' THEN 1 END) AS pedidos_agosto, sum(CASE WHEN periodo = 'jul' THEN total_amount ELSE 0 END) AS jul, sum(CASE WHEN periodo = 'ago' THEN total_amount ELSE 0 END) AS ago FROM base GROUP BY channel) SELECT canal, pedidos_julio, pedidos_agosto, round(jul, 2) AS ingresos_julio, round(ago, 2) AS ingresos_agosto, round(100.0 * (ago - jul) / jul, 2) AS variacion_pct FROM agrupado ORDER BY canal;$c18402$, false, $c18403$Con CASE en lugar de FILTER y una CTE intermedia$c18403$, 1);

