delete from public.exercise_solutions where exercise_id = (select id from public.exercises where slug = $c18557$generos-que-crecen-en-mexico$c18557$);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18558$generos-que-crecen-en-mexico$c18558$), $c18559$WITH escuchas AS (
  SELECT
    ar.genre AS genero,
    p.user_id,
    p.played_at
  FROM plays AS p
  INNER JOIN users AS u ON u.id = p.user_id
  INNER JOIN tracks AS t ON t.id = p.track_id
  INNER JOIN albums AS al ON al.id = t.album_id
  INNER JOIN artists AS ar ON ar.id = al.artist_id
  WHERE u.country = 'MX'
    AND p.played_at >= timestamptz '2025-07-17 00:00:00+00'
    AND p.played_at <  timestamptz '2025-09-15 00:00:00+00'
)
SELECT
  e.genero,
  count(DISTINCT e.user_id) FILTER (WHERE e.played_at < timestamptz '2025-08-16 00:00:00+00') AS oyentes_previos,
  count(DISTINCT e.user_id) FILTER (WHERE e.played_at >= timestamptz '2025-08-16 00:00:00+00') AS oyentes_actuales,
  round(
    100.0 * (
      count(DISTINCT e.user_id) FILTER (WHERE e.played_at >= timestamptz '2025-08-16 00:00:00+00')
      - count(DISTINCT e.user_id) FILTER (WHERE e.played_at < timestamptz '2025-08-16 00:00:00+00')
    ) / count(DISTINCT e.user_id) FILTER (WHERE e.played_at < timestamptz '2025-08-16 00:00:00+00'),
    2
  ) AS variacion_pct
FROM escuchas AS e
GROUP BY e.genero
HAVING count(DISTINCT e.user_id) FILTER (WHERE e.played_at < timestamptz '2025-08-16 00:00:00+00') >= 30
ORDER BY variacion_pct DESC, e.genero;$c18559$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18560$generos-que-crecen-en-mexico$c18560$), $c18561$WITH escuchas AS (SELECT ar.genre AS genero, p.user_id, CASE WHEN p.played_at < timestamptz '2025-08-16 00:00:00+00' THEN 'previa' ELSE 'actual' END AS ventana FROM plays AS p INNER JOIN users AS u ON u.id = p.user_id INNER JOIN tracks AS t ON t.id = p.track_id INNER JOIN albums AS al ON al.id = t.album_id INNER JOIN artists AS ar ON ar.id = al.artist_id WHERE u.country = 'MX' AND p.played_at >= timestamptz '2025-07-17 00:00:00+00' AND p.played_at < timestamptz '2025-09-15 00:00:00+00'), pares AS (SELECT DISTINCT genero, ventana, user_id FROM escuchas), conteos AS (SELECT genero, count(*) FILTER (WHERE ventana = 'previa') AS oyentes_previos, count(*) FILTER (WHERE ventana = 'actual') AS oyentes_actuales FROM pares GROUP BY genero) SELECT genero, oyentes_previos, oyentes_actuales, round(100.0 * (oyentes_actuales - oyentes_previos) / oyentes_previos, 2) AS variacion_pct FROM conteos WHERE oyentes_previos >= 30 ORDER BY variacion_pct DESC, genero;$c18561$, false, $c18562$Contando los oyentes por ventana en una CTE previa$c18562$, 1);

