insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18598$cupon-bienvenida-y-recompra$c18598$), $c18599$WITH entregados AS (
  SELECT
    o.customer_id,
    o.placed_at,
    o.promotion_id,
    row_number() OVER (PARTITION BY o.customer_id ORDER BY o.placed_at, o.id) AS n
  FROM orders AS o
  WHERE o.status = 'delivered'
),
primeros AS (
  SELECT
    e.customer_id,
    e.placed_at,
    CASE WHEN pr.code = 'BIENVENIDA' THEN 'con BIENVENIDA' ELSE 'sin promocion' END AS grupo
  FROM entregados AS e
  LEFT JOIN promotions AS pr ON pr.id = e.promotion_id
  WHERE e.n = 1
    AND (pr.code = 'BIENVENIDA' OR e.promotion_id IS NULL)
    AND e.placed_at >= timestamptz '2025-06-01 00:00:00+00'
    AND e.placed_at <  timestamptz '2025-07-01 00:00:00+00'
),
marcados AS (
  SELECT
    p.grupo,
    CASE WHEN EXISTS (
      SELECT 1
      FROM orders AS o2
      WHERE o2.customer_id = p.customer_id
        AND o2.status = 'delivered'
        AND o2.placed_at >  p.placed_at
        AND o2.placed_at <= p.placed_at + INTERVAL '60 days'
    ) THEN 1 ELSE 0 END AS recompro
  FROM primeros AS p
)
SELECT
  m.grupo,
  count(*) AS clientes,
  sum(m.recompro) AS recompraron,
  round(100.0 * sum(m.recompro) / count(*), 2) AS pct_recompra
FROM marcados AS m
GROUP BY m.grupo
ORDER BY m.grupo;$c18599$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18600$cupon-bienvenida-y-recompra$c18600$), $c18601$WITH primer_fecha AS (SELECT customer_id, min(placed_at) AS primera FROM orders WHERE status = 'delivered' GROUP BY customer_id), primeros AS (SELECT o.customer_id, o.placed_at, CASE WHEN pr.code = 'BIENVENIDA' THEN 'con BIENVENIDA' ELSE 'sin promocion' END AS grupo FROM orders AS o INNER JOIN primer_fecha AS pf ON pf.customer_id = o.customer_id AND pf.primera = o.placed_at LEFT JOIN promotions AS pr ON pr.id = o.promotion_id WHERE o.status = 'delivered' AND (pr.code = 'BIENVENIDA' OR o.promotion_id IS NULL) AND o.placed_at >= timestamptz '2025-06-01 00:00:00+00' AND o.placed_at < timestamptz '2025-07-01 00:00:00+00') SELECT p.grupo, count(*) AS clientes, count(*) FILTER (WHERE EXISTS (SELECT 1 FROM orders AS o2 WHERE o2.customer_id = p.customer_id AND o2.status = 'delivered' AND o2.placed_at > p.placed_at AND o2.placed_at <= p.placed_at + INTERVAL '60 days')) AS recompraron, round(100.0 * count(*) FILTER (WHERE EXISTS (SELECT 1 FROM orders AS o2 WHERE o2.customer_id = p.customer_id AND o2.status = 'delivered' AND o2.placed_at > p.placed_at AND o2.placed_at <= p.placed_at + INTERVAL '60 days')) / count(*), 2) AS pct_recompra FROM primeros AS p GROUP BY p.grupo ORDER BY p.grupo;$c18601$, false, $c18602$Con min() en lugar de row_number() y count FILTER$c18602$, 1);

