    t.amount / ___(f.usd_rate, ___) AS monto_usd
  FROM transactions AS t
  INNER JOIN accounts AS a ON ___ = ___
  ___ JOIN fx_rates AS f
    ON f.currency = ___
   AND f.rate_date = (t.created_at AT TIME ZONE 'UTC')::date
  WHERE t.kind IN ('___', '___')
    AND t.status = '___'
    AND t.created_at >= timestamptz '2025-01-01 00:00:00+00'
    AND t.created_at <  timestamptz '___'
)
SELECT
