insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18679$entrevista-segundo-mas-vendido-por-categoria$c18679$), $c18680$WITH ventas AS (
  SELECT p.category_id, p.id AS product_id, p.name AS product_name, sum(oi.quantity) AS unidades
  FROM order_items AS oi
  INNER JOIN products AS p ON p.id = oi.product_id
  GROUP BY p.category_id, p.id, p.name
),
niveles AS (
  SELECT
    category_id,
    product_name,
    unidades,
    dense_rank() OVER (PARTITION BY category_id ORDER BY unidades DESC) AS nivel
  FROM ventas
)
SELECT
  c.name AS categoria,
  n.product_name,
  n.unidades
FROM niveles AS n
INNER JOIN categories AS c ON c.id = n.category_id
WHERE n.nivel = 2
ORDER BY c.name, n.product_name;$c18680$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18681$entrevista-segundo-mas-vendido-por-categoria$c18681$), $c18682$SELECT c.name AS categoria, n.product_name, n.unidades
FROM (
  SELECT
    category_id,
    product_name,
    unidades,
    dense_rank() OVER (PARTITION BY category_id ORDER BY unidades DESC) AS nivel
  FROM (
    SELECT p.category_id, p.name AS product_name, sum(oi.quantity) AS unidades
    FROM order_items AS oi
    INNER JOIN products AS p ON p.id = oi.product_id
