insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18762$entrevista-comercios-con-cero-alertas$c18762$), $c18763$SELECT
  m.id AS merchant_id,
  m.name,
  m.category,
  count(t.id) AS transacciones_marcadas,
  coalesce(sum(t.amount), 0) AS monto_marcado
FROM merchants AS m
LEFT JOIN transactions AS t
  ON t.merchant_id = m.id
 AND t.is_flagged
 AND t.created_at >= timestamptz '2025-01-01 00:00:00+00'
GROUP BY m.id, m.name, m.category
ORDER BY transacciones_marcadas DESC, m.name, m.id;$c18763$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18764$entrevista-comercios-con-cero-alertas$c18764$), $c18765$SELECT
  m.id AS merchant_id,
  m.name,
  m.category,
  coalesce(f.marcadas, 0) AS transacciones_marcadas,
  coalesce(f.monto, 0) AS monto_marcado
FROM merchants AS m
LEFT JOIN (
  SELECT merchant_id, count(*) AS marcadas, sum(amount) AS monto
  FROM transactions
  WHERE is_flagged AND created_at >= timestamptz '2025-01-01 00:00:00+00'
  GROUP BY merchant_id
) AS f ON f.merchant_id = m.id
ORDER BY transacciones_marcadas DESC, m.name, m.id;$c18765$, false, $c18766$Agregar primero y unir después$c18766$, 1);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18767$entrevista-comercios-con-cero-alertas$c18767$), $c18768$SELECT
  m.id AS merchant_id,
