delete from public.exercise_solutions where exercise_id = (select id from public.exercises where slug = $c18843$entrevista-racha-mas-larga-de-dias$c18843$);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18844$entrevista-racha-mas-larga-de-dias$c18844$), $c18845$WITH dias AS (
  SELECT DISTINCT user_id, (played_at AT TIME ZONE 'UTC')::date AS dia
  FROM plays
),
islas AS (
  SELECT
    user_id,
    dia,
    dia - (row_number() OVER (PARTITION BY user_id ORDER BY dia))::int AS grupo
  FROM dias
),
rachas AS (
  SELECT user_id, grupo, count(*) AS dias_racha, min(dia) AS inicio, max(dia) AS fin
  FROM islas
  GROUP BY user_id, grupo
),
mejor AS (
  SELECT DISTINCT ON (user_id) user_id, dias_racha, inicio, fin
  FROM rachas
  ORDER BY user_id, dias_racha DESC, inicio
)
SELECT m.user_id, u.country, m.dias_racha, m.inicio, m.fin
FROM mejor AS m
INNER JOIN users AS u ON u.id = m.user_id
WHERE m.dias_racha >= 10
ORDER BY m.dias_racha DESC, m.user_id;$c18845$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18846$entrevista-racha-mas-larga-de-dias$c18846$), $c18847$WITH dias AS (
  SELECT DISTINCT user_id, (played_at AT TIME ZONE 'UTC')::date AS dia
  FROM plays
),
islas AS (
  SELECT user_id, dia, dia - (row_number() OVER (PARTITION BY user_id ORDER BY dia))::int AS grupo
  FROM dias
),
rachas AS (
  SELECT user_id, count(*) AS dias_racha, min(dia) AS inicio, max(dia) AS fin
  FROM islas
  GROUP BY user_id, grupo
),
ranking AS (
  SELECT
    user_id, dias_racha, inicio, fin,
    row_number() OVER (PARTITION BY user_id ORDER BY dias_racha DESC, inicio) AS puesto
  FROM rachas
)
SELECT r.user_id, u.country, r.dias_racha, r.inicio, r.fin
FROM ranking AS r
INNER JOIN users AS u ON u.id = r.user_id
WHERE r.puesto = 1 AND r.dias_racha >= 10
ORDER BY r.dias_racha DESC, r.user_id;$c18847$, false, $c18848$ROW_NUMBER para elegir la mejor racha$c18848$, 1);

