insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18882$entrevista-tres-veces-seguidas$c18882$), $c18883$WITH secuencia AS (
  SELECT
    user_id,
    track_id,
    played_at,
    lag(track_id) OVER (PARTITION BY user_id ORDER BY played_at, id) AS anterior_1,
    lag(track_id, 2) OVER (PARTITION BY user_id ORDER BY played_at, id) AS anterior_2
  FROM plays
)
SELECT
  s.user_id,
  s.track_id,
  t.title,
  s.played_at AT TIME ZONE 'UTC' AS tercera_utc
FROM secuencia AS s
INNER JOIN tracks AS t ON t.id = s.track_id
WHERE s.track_id = s.anterior_1
  AND s.track_id = s.anterior_2
ORDER BY s.user_id, tercera_utc;$c18883$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18884$entrevista-tres-veces-seguidas$c18884$), $c18885$WITH ordenadas AS (
  SELECT
    user_id, track_id, played_at, id,
    row_number() OVER (PARTITION BY user_id ORDER BY played_at, id) AS pos_global,
    row_number() OVER (PARTITION BY user_id, track_id ORDER BY played_at, id) AS pos_cancion
  FROM plays
),
bloques AS (
  SELECT
    user_id, track_id, played_at,
    row_number() OVER (PARTITION BY user_id, track_id, pos_global - pos_cancion ORDER BY played_at, id) AS seguidas
  FROM ordenadas
)
SELECT b.user_id, b.track_id, t.title, b.played_at AT TIME ZONE 'UTC' AS tercera_utc
FROM bloques AS b
INNER JOIN tracks AS t ON t.id = b.track_id
WHERE b.seguidas >= 3
ORDER BY b.user_id, tercera_utc;$c18885$, false, $c18886$Brechas e islas sobre la secuencia de reproducciones$c18886$, 1);

