insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18921$entrevista-pareto-de-restaurantes$c18921$), $c18922$WITH gmv AS (
  SELECT r.id AS restaurant_id, r.name AS restaurant_name, sum(o.total) AS gmv
  FROM orders AS o
  INNER JOIN restaurants AS r ON r.id = o.restaurant_id
  WHERE o.status = 'delivered'
  GROUP BY r.id, r.name
),
acumulado AS (
  SELECT
    restaurant_id,
    restaurant_name,
    gmv,
    sum(gmv) OVER (ORDER BY gmv DESC, restaurant_id) AS gmv_acumulado,
    sum(gmv) OVER () AS gmv_total
  FROM gmv
)
SELECT
  row_number() OVER (ORDER BY gmv DESC, restaurant_id) AS posicion,
  restaurant_name,
  gmv,
  round(100.0 * gmv_acumulado / gmv_total, 2) AS share_acumulado_pct
FROM acumulado
WHERE gmv_acumulado - gmv < 0.5 * gmv_total
ORDER BY posicion;$c18922$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18923$entrevista-pareto-de-restaurantes$c18923$), $c18924$WITH gmv AS (
  SELECT r.id AS restaurant_id, r.name AS restaurant_name, sum(o.total) AS gmv
  FROM orders AS o
  INNER JOIN restaurants AS r ON r.id = o.restaurant_id
  WHERE o.status = 'delivered'
  GROUP BY r.id, r.name
),
total AS (SELECT sum(gmv) AS gmv_total FROM gmv),
acumulado AS (
  SELECT
    g.restaurant_id,
    g.restaurant_name,
    g.gmv,
    sum(g.gmv) OVER (ORDER BY g.gmv DESC, g.restaurant_id) AS gmv_acumulado,
    row_number() OVER (ORDER BY g.gmv DESC, g.restaurant_id) AS posicion,
    t.gmv_total
  FROM gmv AS g
  CROSS JOIN total AS t
)
SELECT posicion, restaurant_name, gmv, round(100.0 * gmv_acumulado / gmv_total, 2) AS share_acumulado_pct
FROM acumulado
WHERE gmv_acumulado - gmv < 0.5 * gmv_total
ORDER BY posicion;$c18924$, false, $c18925$El total en una CTE aparte$c18925$, 1);

