delete from public.exercise_solutions where exercise_id = (select id from public.exercises where slug = $c18959$pedidos-por-pais-y-canal-con-subtotales$c18959$);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18960$pedidos-por-pais-y-canal-con-subtotales$c18960$), $c18961$SELECT
  CASE WHEN grouping(c.country) = 1 THEN 'TOTAL' ELSE c.country END AS pais,
  CASE WHEN grouping(o.channel) = 1 THEN 'TOTAL' ELSE o.channel END AS canal,
  count(*) AS pedidos,
  count(DISTINCT o.customer_id) AS clientes
FROM orders AS o
INNER JOIN customers AS c ON c.id = o.customer_id
WHERE o.status = 'delivered'
GROUP BY ROLLUP (c.country, o.channel)
ORDER BY grouping(c.country), pais, grouping(o.channel), canal;$c18961$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c18962$pedidos-por-pais-y-canal-con-subtotales$c18962$), $c18963$WITH bloques AS (
  SELECT c.country AS pais, o.channel AS canal, count(*) AS pedidos, count(DISTINCT o.customer_id) AS clientes
  FROM orders AS o INNER JOIN customers AS c ON c.id = o.customer_id
  WHERE o.status = 'delivered'
  GROUP BY c.country, o.channel
  UNION ALL
  SELECT c.country, 'TOTAL', count(*), count(DISTINCT o.customer_id)
  FROM orders AS o INNER JOIN customers AS c ON c.id = o.customer_id
  WHERE o.status = 'delivered'
  GROUP BY c.country
  UNION ALL
  SELECT 'TOTAL', 'TOTAL', count(*), count(DISTINCT o.customer_id)
  FROM orders AS o INNER JOIN customers AS c ON c.id = o.customer_id
  WHERE o.status = 'delivered'
)
SELECT pais, canal, pedidos, clientes
FROM bloques
ORDER BY (pais = 'TOTAL'), pais, (canal = 'TOTAL'), canal;$c18963$, false, $c18964$Tres consultas unidas con UNION ALL (lo que ROLLUP reemplaza)$c18964$, 1);

