insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19000$cocinas-y-medios-de-pago-en-cubo$c19000$), $c19001$SELECT
  CASE WHEN grouping(r.cuisine) = 1 THEN 'TODAS' ELSE r.cuisine END AS cocina,
  CASE WHEN grouping(o.payment_method) = 1 THEN 'TODOS' ELSE o.payment_method END AS metodo,
  count(*) AS pedidos,
  round(sum(o.total), 2) AS ventas,
  round(avg(o.total), 2) AS ticket_promedio
FROM orders AS o
INNER JOIN restaurants AS r ON r.id = o.restaurant_id
INNER JOIN cities AS c ON c.id = r.city_id
WHERE c.name = 'Buenos Aires'
  AND o.status = 'delivered'
GROUP BY CUBE (r.cuisine, o.payment_method)
ORDER BY grouping(r.cuisine), cocina, grouping(o.payment_method), metodo;$c19001$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19002$cocinas-y-medios-de-pago-en-cubo$c19002$), $c19003$SELECT
  coalesce(r.cuisine, 'TODAS') AS cocina,
  coalesce(o.payment_method, 'TODOS') AS metodo,
  count(*) AS pedidos,
  round(sum(o.total), 2) AS ventas,
  round(avg(o.total), 2) AS ticket_promedio
FROM orders AS o
INNER JOIN restaurants AS r ON r.id = o.restaurant_id
INNER JOIN cities AS c ON c.id = r.city_id
WHERE c.name = 'Buenos Aires' AND o.status = 'delivered'
GROUP BY CUBE (r.cuisine, o.payment_method)
ORDER BY grouping(r.cuisine), cocina, grouping(o.payment_method), metodo;$c19003$, false, $c19004$Etiquetar con COALESCE (posible porque ninguna columna tiene NULL real)$c19004$, 1);

