insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19042$cancion-estrella-de-cada-artista$c19042$), $c19043$SELECT
  a.name AS artista,
  t.cancion,
  t.reproducciones
FROM artists AS a
CROSS JOIN LATERAL (
  SELECT tr.title AS cancion, count(*) AS reproducciones
  FROM plays AS p
  INNER JOIN tracks AS tr ON tr.id = p.track_id
  INNER JOIN albums AS al ON al.id = tr.album_id
  WHERE al.artist_id = a.id
    AND p.played_at >= '2025-01-01T00:00:00Z'::timestamptz
  GROUP BY tr.id, tr.title
  ORDER BY count(*) DESC, tr.title
  LIMIT 1
) AS t
WHERE a.genre = 'cumbia'
ORDER BY t.reproducciones DESC, a.name;$c19043$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19044$cancion-estrella-de-cada-artista$c19044$), $c19045$WITH conteos AS (
  SELECT
    al.artist_id,
    tr.title AS cancion,
    count(*) AS reproducciones,
    row_number() OVER (PARTITION BY al.artist_id ORDER BY count(*) DESC, tr.title) AS puesto
  FROM plays AS p
  INNER JOIN tracks AS tr ON tr.id = p.track_id
  INNER JOIN albums AS al ON al.id = tr.album_id
  WHERE p.played_at >= '2025-01-01T00:00:00Z'::timestamptz
  GROUP BY al.artist_id, tr.id, tr.title
)
SELECT a.name AS artista, c.cancion, c.reproducciones
FROM conteos AS c
INNER JOIN artists AS a ON a.id = c.artist_id
WHERE c.puesto = 1 AND a.genre = 'cumbia'
ORDER BY c.reproducciones DESC, a.name;$c19045$, false, $c19046$Numerar con ROW_NUMBER en una CTE y quedarse con el puesto 1$c19046$, 1);

