insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19124$ventas-por-categoria-raiz$c19124$), $c19125$WITH RECURSIVE arbol(id, raiz) AS (
  SELECT c.id, c.name
  FROM categories AS c
  WHERE c.parent_id IS NULL
  UNION ALL
  SELECT h.id, a.raiz
  FROM categories AS h
  INNER JOIN arbol AS a ON a.id = h.parent_id
)
SELECT
  a.raiz AS categoria_raiz,
  count(DISTINCT p.id) AS productos,
  count(DISTINCT o.id) AS pedidos,
  sum(oi.quantity) AS unidades
FROM arbol AS a
INNER JOIN products AS p ON p.category_id = a.id
INNER JOIN order_items AS oi ON oi.product_id = p.id
INNER JOIN orders AS o ON o.id = oi.order_id
WHERE o.status = 'delivered'
GROUP BY a.raiz
ORDER BY unidades DESC, a.raiz;$c19125$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19126$ventas-por-categoria-raiz$c19126$), $c19127$WITH RECURSIVE arbol(id, raiz) AS (
  SELECT c.id, c.name FROM categories AS c WHERE c.parent_id IS NULL
  UNION ALL
  SELECT h.id, a.raiz FROM categories AS h INNER JOIN arbol AS a ON a.id = h.parent_id
)
SELECT
  a.raiz AS categoria_raiz,
  count(DISTINCT p.id) AS productos,
  count(DISTINCT oi.order_id) AS pedidos,
  sum(oi.quantity) AS unidades
FROM order_items AS oi
INNER JOIN orders AS o ON o.id = oi.order_id AND o.status = 'delivered'
INNER JOIN products AS p ON p.id = oi.product_id
INNER JOIN arbol AS a ON a.id = p.category_id
GROUP BY a.raiz
ORDER BY unidades DESC, a.raiz;$c19127$, false, $c19128$Mismo árbol, partiendo de order_items$c19128$, 1);

