insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19205$ficha-json-de-artistas-del-bimestre$c19205$), $c19206$WITH escuchas AS (
  SELECT
    al.artist_id,
    count(*) AS reproducciones,
    count(DISTINCT p.user_id) AS oyentes
  FROM plays AS p
  INNER JOIN tracks AS tr ON tr.id = p.track_id
  INNER JOIN albums AS al ON al.id = tr.album_id
  WHERE p.played_at >= '2025-07-01T00:00:00Z'::timestamptz
    AND p.played_at < '2025-09-01T00:00:00Z'::timestamptz
  GROUP BY al.artist_id
)
SELECT
  a.name AS artista,
  jsonb_build_object(
    'pais', a.country,
    'genero', a.genre,
    'oyentes', e.oyentes,
    'reproducciones', e.reproducciones,
    'participacion', round(100.0 * e.reproducciones / sum(e.reproducciones) OVER (), 2)
  )::text AS payload
FROM escuchas AS e
INNER JOIN artists AS a ON a.id = e.artist_id
ORDER BY e.reproducciones DESC, a.name
LIMIT 10;$c19206$, true, 'reference', 0);

