delete from public.exercise_solutions where exercise_id = (select id from public.exercises where slug = $c19288$estado-de-resultados-mensual-tiendaviva$c19288$);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19289$estado-de-resultados-mensual-tiendaviva$c19289$), $c19290$WITH cobrados AS (
  SELECT
    o.id,
    c.country,
    o.currency,
    date_trunc('month', o.created_at AT TIME ZONE 'UTC')::date AS month,
    p.amount
  FROM orders o
  JOIN customers c ON c.id = o.customer_id
  JOIN payments p ON p.order_id = o.id AND p.status IN ('approved', 'refunded')
)
SELECT
  b.country,
  b.currency,
  b.month,
  count(*) AS paid_orders,
  sum(b.amount) AS gross_amount,
  coalesce(sum(r.refund_amount), 0) AS refunded_amount,
  sum(b.amount) - coalesce(sum(r.refund_amount), 0) AS net_amount
FROM cobrados b
LEFT JOIN returns r ON r.order_id = b.id
GROUP BY b.country, b.currency, b.month
ORDER BY b.country, b.month;$c19290$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19291$estado-de-resultados-mensual-tiendaviva$c19291$), $c19292$WITH cobrados AS (
  SELECT
    o.id,
    c.country,
    o.currency,
    date_trunc('month', o.created_at AT TIME ZONE 'UTC')::date AS month,
    p.amount
  FROM orders o
  JOIN customers c ON c.id = o.customer_id
  JOIN payments p ON p.order_id = o.id AND p.status IN ('approved', 'refunded')
),
devoluciones AS (
  SELECT order_id, sum(refund_amount) AS refunded
  FROM returns
  GROUP BY order_id
)
SELECT
  b.country,
  b.currency,
  b.month,
  count(*) AS paid_orders,
  sum(b.amount) AS gross_amount,
  coalesce(sum(d.refunded), 0) AS refunded_amount,
  sum(b.amount) - coalesce(sum(d.refunded), 0) AS net_amount
FROM cobrados b
LEFT JOIN devoluciones d ON d.order_id = b.id
GROUP BY b.country, b.currency, b.month
ORDER BY b.country, b.month;$c19292$, false, $c19293$Devoluciones agregadas por pedido antes de unir$c19293$, 1);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19294$estado-de-resultados-mensual-tiendaviva$c19294$), $c19295$WITH cobrados AS (
  SELECT
    o.id,
    c.country,
    o.currency,
    date_trunc('month', o.created_at AT TIME ZONE 'UTC')::date AS month,
    p.amount,
    coalesce((SELECT sum(r.refund_amount) FROM returns r WHERE r.order_id = o.id), 0) AS refunded
  FROM orders o
  JOIN customers c ON c.id = o.customer_id
  JOIN payments p ON p.order_id = o.id AND p.status IN ('approved', 'refunded')
)
SELECT
  country,
  currency,
  month,
  count(*) AS paid_orders,
  sum(amount) AS gross_amount,
  sum(refunded) AS refunded_amount,
  sum(amount) - sum(refunded) AS net_amount
FROM cobrados
GROUP BY country, currency, month
ORDER BY country, month;$c19295$, false, $c19296$Reembolso por pedido con una subconsulta escalar$c19296$, 2);

