insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19334$desempeno-de-restaurantes-cdmx$c19334$), $c19335$SELECT
  r.name AS restaurant,
  r.cuisine,
  count(*) AS delivered_orders,
  round(sum(o.total), 2) AS gmv,
  round(sum(o.total * r.commission_pct / 100), 2) AS commission_revenue,
  round(avg(ra.restaurant_rating), 2) AS avg_rating,
  round(100.0 * count(*) FILTER (WHERE o.delivered_at > o.placed_at + o.promised_minutes * interval '1 minute') / count(*), 2) AS late_pct
FROM orders o
JOIN restaurants r ON r.id = o.restaurant_id
JOIN cities ci ON ci.id = r.city_id
LEFT JOIN ratings ra ON ra.order_id = o.id
WHERE ci.name = 'Ciudad de México'
  AND o.status = 'delivered'
  AND o.placed_at AT TIME ZONE 'UTC' >= '2025-01-01'
  AND o.placed_at AT TIME ZONE 'UTC' < '2025-07-01'
GROUP BY r.id, r.name, r.cuisine
HAVING count(*) >= 25
ORDER BY commission_revenue DESC, restaurant;$c19335$, true, 'reference', 0);

