insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19427$gasto-por-rubro-en-dolares$c19427$), $c19428$WITH pagos AS (
  SELECT
    t.status,
    a.user_id,
    m.category,
    t.amount / coalesce(f.usd_rate, 1) AS amount_usd
  FROM transactions t
  JOIN accounts a ON a.id = t.account_id
  JOIN merchants m ON m.id = t.merchant_id
  LEFT JOIN fx_rates f
    ON f.currency = t.currency
   AND f.rate_date = (t.created_at AT TIME ZONE 'UTC')::date
  WHERE t.kind IN ('card_payment', 'qr_payment')
    AND t.status IN ('completed', 'reversed')
    AND t.created_at AT TIME ZONE 'UTC' >= '2025-01-01'
    AND t.created_at AT TIME ZONE 'UTC' < '2025-07-01'
)
SELECT
  category,
  count(*) FILTER (WHERE status = 'completed') AS completed_payments,
  count(*) FILTER (WHERE status = 'reversed') AS reversed_payments,
  count(DISTINCT user_id) FILTER (WHERE status = 'completed') AS users,
  round(sum(amount_usd) FILTER (WHERE status = 'completed'), 2) AS amount_usd,
  round(sum(amount_usd) FILTER (WHERE status = 'completed') / count(*) FILTER (WHERE status = 'completed'), 2) AS avg_ticket_usd,
  round(100.0 * count(*) FILTER (WHERE status = 'reversed') / count(*), 2) AS reversed_pct
FROM pagos
GROUP BY category
ORDER BY amount_usd DESC;$c19428$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19429$gasto-por-rubro-en-dolares$c19429$), $c19430$WITH pagos AS (
  SELECT
    t.status,
    a.user_id,
    m.category,
    CASE
      WHEN t.currency = 'USD' THEN t.amount
      ELSE t.amount / (
        SELECT f.usd_rate FROM fx_rates f
        WHERE f.currency = t.currency
          AND f.rate_date = (t.created_at AT TIME ZONE 'UTC')::date
      )
    END AS amount_usd
  FROM transactions t
  JOIN accounts a ON a.id = t.account_id
  JOIN merchants m ON m.id = t.merchant_id
  WHERE t.kind IN ('card_payment', 'qr_payment')
    AND t.status IN ('completed', 'reversed')
    AND t.created_at AT TIME ZONE 'UTC' >= '2025-01-01'
    AND t.created_at AT TIME ZONE 'UTC' < '2025-07-01'
)
SELECT
  category,
  count(*) FILTER (WHERE status = 'completed') AS completed_payments,
  count(*) FILTER (WHERE status = 'reversed') AS reversed_payments,
  count(DISTINCT user_id) FILTER (WHERE status = 'completed') AS users,
  round(sum(amount_usd) FILTER (WHERE status = 'completed'), 2) AS amount_usd,
  round(avg(amount_usd) FILTER (WHERE status = 'completed'), 2) AS avg_ticket_usd,
  round(100.0 * count(*) FILTER (WHERE status = 'reversed') / count(*), 2) AS reversed_pct
FROM pagos
GROUP BY category
ORDER BY amount_usd DESC;$c19430$, false, $c19431$Conversión resuelta con CASE sobre la moneda$c19431$, 1);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19432$gasto-por-rubro-en-dolares$c19432$), $c19433$WITH pagos AS (
  SELECT
    t.status,
    a.user_id,
    m.category,
    t.amount / coalesce(f.usd_rate, 1) AS amount_usd
  FROM transactions t
  JOIN accounts a ON a.id = t.account_id
  JOIN merchants m ON m.id = t.merchant_id
  LEFT JOIN fx_rates f
    ON f.currency = t.currency
   AND f.rate_date = (t.created_at AT TIME ZONE 'UTC')::date
  WHERE t.kind IN ('card_payment', 'qr_payment')
    AND t.status IN ('completed', 'reversed')
    AND t.created_at AT TIME ZONE 'UTC' >= '2025-01-01'
    AND t.created_at AT TIME ZONE 'UTC' < '2025-07-01'
)
SELECT
  category,
  sum(CASE WHEN status = 'completed' THEN 1 ELSE 0 END) AS completed_payments,
  sum(CASE WHEN status = 'reversed' THEN 1 ELSE 0 END) AS reversed_payments,
  count(DISTINCT CASE WHEN status = 'completed' THEN user_id END) AS users,
  round(sum(CASE WHEN status = 'completed' THEN amount_usd END), 2) AS amount_usd,
  round(sum(CASE WHEN status = 'completed' THEN amount_usd END) / sum(CASE WHEN status = 'completed' THEN 1 ELSE 0 END), 2) AS avg_ticket_usd,
  round(100.0 * sum(CASE WHEN status = 'reversed' THEN 1 ELSE 0 END) / count(*), 2) AS reversed_pct
FROM pagos
GROUP BY category
ORDER BY amount_usd DESC;$c19433$, false, $c19434$Conteos condicionales con CASE$c19434$, 2);

