insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19471$panorama-de-transferencias-p2p$c19471$), $c19472$SELECT
  u.country,
  tr.currency,
  count(*) FILTER (WHERE tr.status = 'completed') AS completed_transfers,
  count(DISTINCT origen.user_id) FILTER (WHERE tr.status = 'completed') AS senders,
  count(DISTINCT destino.user_id) FILTER (WHERE tr.status = 'completed') AS receivers,
  round(sum(tr.amount) FILTER (WHERE tr.status = 'completed'), 2) AS completed_amount,
  round(percentile_cont(0.5) WITHIN GROUP (ORDER BY CASE WHEN tr.status = 'completed' THEN tr.amount END)::numeric, 2) AS median_amount,
  round(100.0 * count(*) FILTER (WHERE tr.status = 'failed') / count(*), 2) AS failed_pct
FROM transfers tr
JOIN accounts origen ON origen.id = tr.from_account_id
JOIN accounts destino ON destino.id = tr.to_account_id
JOIN users u ON u.id = origen.user_id
WHERE tr.created_at AT TIME ZONE 'UTC' >= '2024-07-01'
  AND tr.created_at AT TIME ZONE 'UTC' < '2025-07-01'
GROUP BY u.country, tr.currency
ORDER BY completed_amount DESC;$c19472$, true, 'reference', 0);

