insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19632$optimizacion-restaurantes-con-actividad$c19632$), $c19633$SELECT r.id AS restaurant_id, r.name
FROM restaurants AS r
WHERE r.is_active
  AND EXISTS (
    SELECT 1
    FROM orders AS o
    WHERE o.restaurant_id = r.id
      AND o.status = 'delivered'
      AND o.placed_at >= TIMESTAMPTZ '2025-08-01 00:00:00+00'
      AND o.placed_at <  TIMESTAMPTZ '2025-09-01 00:00:00+00'
  )
ORDER BY r.id;$c19633$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19634$optimizacion-restaurantes-con-actividad$c19634$), $c19635$SELECT r.id AS restaurant_id, r.name
FROM restaurants AS r
WHERE r.is_active
  AND r.id IN (
    SELECT o.restaurant_id
    FROM orders AS o
    WHERE o.status = 'delivered'
      AND o.placed_at >= TIMESTAMPTZ '2025-08-01 00:00:00+00'
      AND o.placed_at <  TIMESTAMPTZ '2025-09-01 00:00:00+00'
  )
ORDER BY r.id;$c19635$, false, $c19636$Con IN sobre una subconsulta no correlacionada$c19636$, 1);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19637$optimizacion-restaurantes-con-actividad$c19637$), $c19638$WITH activos_agosto AS (
  SELECT o.restaurant_id
  FROM orders AS o
  WHERE o.status = 'delivered'
    AND o.placed_at >= TIMESTAMPTZ '2025-08-01 00:00:00+00'
    AND o.placed_at <  TIMESTAMPTZ '2025-09-01 00:00:00+00'
  GROUP BY o.restaurant_id
)
SELECT r.id AS restaurant_id, r.name
FROM restaurants AS r
JOIN activos_agosto AS a ON a.restaurant_id = r.id
WHERE r.is_active
ORDER BY r.id;$c19638$, false, $c19639$Agregando primero los pedidos y uniendo un resultado ya al grano de restaurante$c19639$, 2);

