delete from public.exercise_solutions where exercise_id = (select id from public.exercises where slug = $c19677$optimizacion-reducir-antes-de-unir-categorias$c19677$);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19678$optimizacion-reducir-antes-de-unir-categorias$c19678$), $c19679$WITH entregados AS (
  SELECT o.id
  FROM orders AS o
  JOIN restaurants AS r ON r.id = o.restaurant_id
  WHERE r.city_id = 5
    AND o.status = 'delivered'
    AND o.placed_at >= TIMESTAMPTZ '2025-08-01 00:00:00+00'
    AND o.placed_at <  TIMESTAMPTZ '2025-09-01 00:00:00+00'
)
SELECT
  m.category,
  sum(oi.quantity)::int AS unidades,
  round(sum(oi.quantity * oi.unit_price), 2) AS monto
FROM entregados AS e
JOIN order_items AS oi ON oi.order_id = e.id
JOIN menu_items AS m ON m.id = oi.menu_item_id
GROUP BY m.category
ORDER BY unidades DESC;$c19679$, true, 'reference', 0);

insert into public.exercise_solutions (exercise_id, sql, is_reference, approach_label, sort_order) values ((select id from public.exercises where slug = $c19680$optimizacion-reducir-antes-de-unir-categorias$c19680$), $c19681$SELECT
  m.category,
  sum(oi.quantity)::int AS unidades,
  round(sum(oi.quantity * oi.unit_price), 2) AS monto
FROM orders AS o
JOIN restaurants AS r ON r.id = o.restaurant_id
JOIN order_items AS oi ON oi.order_id = o.id
JOIN menu_items AS m ON m.id = oi.menu_item_id
WHERE r.city_id = 5
  AND o.status = 'delivered'
  AND o.placed_at >= TIMESTAMPTZ '2025-08-01 00:00:00+00'
  AND o.placed_at <  TIMESTAMPTZ '2025-09-01 00:00:00+00'
GROUP BY m.category
ORDER BY unidades DESC;$c19681$, false, $c19682$Todo en una sola consulta, sin CTE$c19682$, 1);

